COLLDATA("khalqafaalur","ur",[[1,"سفیان بن عیینہ رحمہ اللہ (المتوفیٰ: 198ھ) فرماتے ہیں: میں نے اپنی ستر سالہ زندگی میں اپنے جن مشایخ سے ملاقات کی ہیں، جن میں عمرو بن دینار رحمہ اللہ (المتوفیٰ: 126ھ)بھی شامل ہیں، ان سب کا یہی قول تھا کہ ’’قرآن اللہ کا کلام ہے، مخلوق ہرگزنہیں ہے۔‘‘","",{"k":"التاریخ الکبیر للبخاري (2/338)۔ والأوسط (2/232)۔ السنن الکبری للبیہقي (10/205)۔ الأسماء والصفات للبیہقي (1/597)۔ شرح أصول اعتقاد أھل السنۃ لللالکائي (2/236)"}],[2,"سفیان ثوری رحمہ اللہ (المتوفیٰ: 161ھ)فرماتے ہیں کہ مجھے حماد بن ابی سلیمان (المتوفیٰ: 120ھ)نے کہا: ’’ابو فلاں مشرک کو میرا پیغام پہنچا دو کہ میں اس کے دین سے بیزار ہوں۔‘‘ سفیان ثوری کہتے ہیں: ’’دراصل ابو فلاں اس بات کا قائل تھا کہ ’’قرآن مخلوق ہے۔‘‘","",{"k":"الضعفاء للعقیلي (4/1407)"}],[3,"حبیب بن ابی حبیب (المتوفیٰ: 162ھ)کہتے ہیں کہ میں عید الاضحیٰ کے روز خالد بن عبد اللہ قَسْرِی (المتوفیٰ: 126ھ)کے پاس واسط شہر میں حاضر ہوا۔ تو (نماز ِ عید کے بعد) خالد نے کہا: ’’لوگو! جاؤ اور جاکر اپنے جانور ذبح کرو۔ اللہ تعالیٰ تمہاری قربانیاں قبول فرمائے۔ میں جعد بن درہم کو ذبح کرنے لگا ہوں جس کا گمان ہے کہ اللہ تعالیٰ نے ابراہیم علیہ السلام کو خلیل اور موسیٰ علیہ السلام کو کلیم نہیں بنایا۔ اللہ تعالیٰ جعد بن درہم کے قول سے بہت بلند وبالا ہے۔ ‘‘ پھر خالد منبر سے اترا اور اس نے جعد کو ذبح کردیا۔","",{"k":"التاريخ الکبیر للبخاري (1/64)۔ والرد علی الجہمیۃ للدارمي (ص 17، 182)۔ والسنۃ للخلال (5/87)"}],[4,"امام بخاری رحمہ اللہ (المتوفیٰ: 256ھ)فرماتے ہیں: قتیبہ رحمہ اللہ کا قول ہے:’’ مجھے معلوم ہوا ہے کہ جہم بن صفوان نے یہ (ملحدانہ) باتیں جعد بن درہم سے ہی سیکھی تھیں۔‘‘"],[5,"ابو زکریا یحییٰ بن یوسف زِمِّی(المتوفیٰ: 123ھ تقریباً)کہتے ہیں کہ میں عبد اللہ بن ادریس (المتوفیٰ: 192ھ)کے پاس موجود تھا کہ ایک شخص ان کے پاس آیا اور اس نے کہا: ’’اے ابو محمد! تم ان لوگوں کے بارے میں کیا کہتے ہو جو اس بات کے قائل ہیں کہ ’’قرآن مخلوق ہے۔‘‘ عبد اللہ نے پوچھا: ’’کیا وہ یہودی ہیں؟‘‘ اس نے کہا: ’’نہیں۔‘‘ پوچھا: ’’تو کیا عیسائی ہیں؟‘‘ کہا: ’’نہیں۔‘‘ پوچھا: ’’پھر مجوسی ہوں گے؟‘‘ کہا: ’’نہیں۔‘‘ عبد اللہ نے پوچھا: ’’تو پھر کون ہیں؟‘‘ کہنے لگا: ’’اہل توحید ہیں۔‘‘ عبد اللہ نے کہا: ’’یہ اہل توحید نہیں ہیں۔ یہ تو زندیقوں کا ٹولہ ہے۔یاد رکھنا! جو شخص یہ دعویٰ کرتاہے کہ قرآن مخلوق ہے تو یقیناً وہ یہ دعویٰ بھی کرتا ہے کہ اللہ بھی مخلوق ہے۔فرمان الٰہی ہے:\n﴿ بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ ﴾ [الفاتحۃ: ۱]\n’’اللہ کے نام کے ساتھ جو بہت مہربان، نہایت رحم کرنے والا ہے۔‘‘\nتو اللہ مخلوق نہیں ہوسکتا۔ رحمان بھی مخلوق نہیں ہوسکتا۔ رحیم بھی مخلوق نہیں ہوسکتا۔ یہی زندیقیت کی بنیاد ہے۔ جو شخص اس بات کا قائل ہے، اس پر اللہ کی لعنت ہو۔ ایسے لوگوں کے ساتھ نہ بیٹھو اور نہ ان سے شادی بیاہ کرو۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد (1/113)۔ الشریعۃ للآجري (1/496)"}],[6,"وہب بن جریر رحمہ اللہ (المتوفیٰ: 206ھ)کہتے ہیں: ’’جہمیہ زندیقوں کا ٹولہ ہے۔ وہ یہ کہنا چاہتے ہیں کہ اللہ عرش پر مستوی نہیں ہے۔‘‘","",{"k":"رواہ الأثرم کما في اجتماع جیوش الإسلامیۃ لابن القیم (ص 137)"}],[7,"یزید بن ہارون رحمہ اللہ (المتوفیٰ: 206ھ)نے اللہ کی قسم کھائی جس کے علاوہ کوئی معبود ِ حقیقی نہیں ہے کہ جو شخص اس بات کا قائل ہے کہ ’’قرآن مخلوق ہے تو وہ زندیق ہے۔ اس سے توبہ کروائی جائے گی۔ اگر توبہ کرلے تو ٹھیک، وگرنہ اس کا سر تن سے جدا کردیا جائے۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد (1/122)۔ السنۃ للخلال (6/93 – 94)۔ الشریعۃ للآجري (1/503)"}],[8,"ابو بکر بن عیاش (المتوفیٰ: 194ھ)سے کہا گیا: بغداد میں کچھ لوگ ایسے ہیں جو کہتے ہیں کہ ’’قرآن مخلوق ہے۔‘‘ تو انہوں نے کہا: ’’تمہارا ستیا ناس ہوجائے۔ ایسا کون کہتا ہے؟ جو بھی کہتا ہے کہ قرآن مخلوق ہے تو اس پر اللہ کی لعنت ہو۔ وہ کافر اور زندیق ہے۔ ایسے لوگوں کے ساتھ نہ بیٹھا کرو۔‘‘","",{"k":"مسائل أحمد لأبي داؤد (ص 267)۔ السنۃ للخلال (6/94، 7/34 – 44)۔ الشریعۃ للآجري (1/499)"}],[9,"سفیان ثوری رحمہ اللہ فرماتے ہیں: ’’جو شخص اس بات کا قائل ہے کہ قرآن مخلوق ہے، وہ کافر ہے۔‘‘","",{"k":"السنۃ للخلال (7/38)۔ السنۃ لعبد اللہ بن أحمد (1/107)"}],[10,"حماد بن زید رحمہ اللہ (المتوفیٰ: 179ھ)فرماتے ہیں: ’’قرآن اللہ کا کلام ہے، جسے جبرائیل علیہ السلام لائے ہیں۔ جو لوگ اس کے (مخلوق یا غیر مخلوق ہونے کے) بارے میں جھگڑ رہے ہیں، وہ یہ کہنا چاہ رہے ہیں کہ آسمان پر کوئی الٰہ نہیں ہے۔‘‘","",{"k":"مسند أحمد (6/457)۔ السنۃ لعبد اللہ بن أحمد (1/117 – 118)۔ السنۃ للخلال (5/91، 127)"}],[11,"عبد اللہ بن مبارک رحمہ اللہ (المتوفیٰ: 181ھ)فرماتے ہیں: ’’جو شخص اس بات کا قائل ہے کہ یہ الفاظ:\n﴿ إِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ ﴾ [طہ: ۱۴]\n’’یقیناً میں اللہ ہوں، میرے علاوہ کوئی معبودِ حقیقی نہیں ہے۔‘‘\nمخلوق ہیں، وہ کافر ہے۔ کیونکہ کسی مخلوق کے لیے ایسا کہنا جائز نہیں۔‘‘","",{"k":"الرد علی الجہمیۃ لأبي حاتم الرازي کما في العلو للعلي الغفار للذھبي (ص 111)۔ الرد علی الجہمیۃ للدارمي (ص 537)۔ السنۃ لعبد اللہ بن أحمد (1/110 – 111)"}],[12,"اسی طرح انہوں نے اشعار میں بھی فرمایا ہے:\n«فَلَا أَقُولُ بِقَوْلِ الْجَهْمِ إِنَّ لَهُ قَوْلًا يُضَارِعُ قَوْلَ الشِّرْكِ أَحْيَانَا»\n«وَلَا أَقُولُ تَخَلَّى مِنْ بَرِيَّتِهِ رَبُّ الْعِبَادِ وَوَلَّى الْأَمْرَ شَيْطَانَا»\n«مَا قَالَ فِرْعَوْنُ هَذَا فِي تَجَبُّرِهِ فِرْعَوْنُ مُوسَى وَلَا فِرْعَوْنُ هَامَانَا»\n’’میں جہم بن صفوان کی باتوں کا قائل نہیں ہوں۔ بلا شبہ اس کی باتیں بعض اوقات مشرکانہ باتوں کے مشابہ ہوتی ہیں۔ نہ ہی میں اس بات کا قائل ہوں کہ رب العباد اپنی مخلوق سے علیحدہ ہوچکا ہے اور شیطان اس کے معاملات کا والی بن گیا ہے۔ موسیٰ علیہ السلام اورہامان والے فرعون نے بھی اپنی سرکشی کے باوجود اس طرح کی باتیں نہیں کیں۔‘‘","",{"k":"سیر أعلام النبلاء للذھبي (8/413 – 414)۔ طبقات الشافعیۃ الکبری للسبکي (1/287)"}],[13,"عبد اللہ بن مبارک رحمہ اللہ فرماتے ہیں: ’’ہم جہمیہ کی طرح اس بات کے قائل نہیں ہیں کہ اللہ تعالیٰ یہاں زمین پر ہے، بلکہ وہ تو اپنے عرش پر مستوی ہے۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد: 1/111، 174 – 175، الرد علی بشر المریسي للدارمي: 1/224 الأسماء والصفات للبیہقي: 2/335 – 336"}],[14,"ان سے کسی نے پوچھا: ’’ہم اپنے رب کو کیسے پہچان سکتے ہیں؟ ‘‘تو انہوں نے فرمایا: ’’وہ آسمانوں سے اوپر اپنے عرش پر ہے۔‘‘","",{"k":"أیضاً"}],[15,"انہوں نے ایک جہمی سے کہا: ’’کیا تمہارا پیٹ اس (اللہ) سے خالی ہے؟‘‘ تو وہ لاجواب ہوگیا۔"],[16,"اسی طرح انہوں نے فرمایا: ’’جو شخص اس بات کا قائل ہے کہ الفاظ: ﴿ لَآ إِلَٰهَ إِلَّا هُوَ ﴾ [البقرۃ: ۲۵۵] مخلوق ہیں تو وہ کافر ہے۔ ہم یہود ونصاریٰ کی باتیں بیان کرلیتے ہیں لیکن جہمیہ کی باتیں نقل کرنے کی ہمت ہمارے اندر نہیں ہے۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد (1/111)۔ الرد علی الجہمیۃ للدارمي (ص 115)۔ السنۃ للخلال (5/89 – 98)"}],[17,"جعفر صادق بن محمد رحمہ اللہ (المتوفیٰ: 148ھ)فرماتے ہیں: ’’قرآن اللہ کا کلام ہے، مخلوق ہرگز نہیں ہے۔‘‘","",{"k":"مسائل أحمد لأبي داؤد (ص 265)۔ النقض علی بشر المریسي (1/571 – 572)۔ صریح السنۃ للطبري (ص 19)"}],[18,"سعید بن عامر رحمہ اللہ (المتوفیٰ: 208 ھ)کا قول ہے: ’’جہمیہ کی باتیں یہود ونصاریٰ سے بھی زیادہ بُری ہیں۔ یہود ونصاریٰ اور دیگر اہلِ ادیان کا اس بات پر اجماع ہے کہ اللہ تبارک وتعالیٰ عرش پر ہے۔ جبکہ جہمیہ کہتے ہیں کہ عرش پر کوئی نہیں ہے۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد والرد علی الجہمیۃ لأبي حاتم کما في درء تعارض العقل النقل لابن تیمیۃ: 6/261 واجتماع الجیوش الإسلامیۃ لابن القیم، ص: 215 والعلو للذھبي، ص: 117"}],[19,"عبد اللہ بن شوذب رحمہ اللہ (المتوفیٰ: 156ھ)کہتے ہیں کہ جہم بن صفوان نے شک کی بناء پر چالیس دن نماز نہیں پڑھی۔ اس کی وجہ یہ بنی کہ کسی سُمَنِی (مشرک/ کافر / بت پرست/ فلسفی) سے اس کا مناظرہ ہوا۔ تو یہ (اللہ تعالیٰ کے بارے میں) شک میں پڑ گیا اور چالیس دن تک نماز پڑھنے سے رُکا رہا۔\nضمرہ (المتوفیٰ: 202ھ)کہتے ہیں کہ ابن شوذب نے اسے (جہم کو) دیکھا ہے۔","",{"k":"السنۃ للخلال (5/82)۔ ابن بطۃ (2/89، 2/86)۔ الللالکائي (3/378)"}],[20,"عبد العزیز بن ابی سلمہ الماجِشُون(المتوفیٰ: 164ھ)کا قول ہے: ’’جہم بن صفوان کا کلام بے معنیٰ صفت اور بےبنیاد عمارت ہے۔ اس کا شمار کبھی بھی اہل علم حضرات میں نہیں ہوا۔ کسی نے جہم سے ایسے شخص کے بارے میں سوال کیا جس نے رخصتی سے پہلے اپنی بیوی کو طلاق دے دی تھی تو جہم نے کہا: ’’اس عورت پر عدت گزارنا لازم ہے۔‘‘!! اپنی جہالت کی بناء پر اس نے اس مسئلہ میں کتاب اللہ کی مخالفت کی ہے کیونکہ قرآن میں اللہ تعالیٰ کا فرمان ہے:\n﴿ فَمَا لَكُمۡ عَلَيۡهِنَّ مِنۡ عِدَّةٍ تَعۡتَدُّونَهَاۖ ﴾ [الأحزاب: ۴۹]\n’’تو ان کے ذمہ تمہاری کوئی عدت واجب نہیں ہے جس کی گنتی تمہیں شمار کرنی ہو۔‘‘","",{"k":"التسعینیۃ لابن تیمیۃ (1/244)۔ الصواعق المرسلۃ لابن القیم (4/1399)"}],[21,"علی بن عاصم (المتوفیٰ: 201ھ)کہتے ہیں: ’’جو لوگ یہ کہتے ہیں کہ اللہ کی اولاد ہے، وہ کفر میں ان لوگوں سے زیادہ بڑھے ہوئے نہیں ہیں جو کہتے ہیں کہ اللہ کلام نہیں کرتا۔‘‘","",{"k":"الإبانۃ لابن بطۃ (2/106، 322)"}],[22,"مزید فرمایا: ’’بشر مریسی اور اس کے ساتھیوں سے دور رہو کیونکہ ان کی باتیں زندیقیت کی طرف لے جانے والی ہیں۔ میں نے بذاتِ خود ان کے گرو گھنٹال جہم بن صفوان سے گفتگو کی ہے۔ وہ یہ ثابت نہیں کرسکا کہ آسمان پر کوئی الٰہ ہے۔‘‘"],[23,"اسماعیل بن ابی اویس رحمہ اللہ (المتوفیٰ: 226 ھ)جہمیہ کو ’’عراقی زندیق‘‘ کہتے تھے۔"],[24,"کسی نے ان سے کہا: ’’میں نے کسی کو کہتے ہوئے سنا ہے کہ قرآن مخلوق ہے۔‘‘ تو انہوں نے فرمایا: ’’یہ زندیق ہیں۔ اللہ کی قسم! جب میں نے بغداد میں عباسی (خلیفہ)کو یہی بات کہتے ہوئے سنا تھا تو اس کلام سے بچنے کےلیے بغداد چھوڑ کر یمن چلا گیا تھا۔‘‘"],[25,"خارجہ بن مصعب رحمہ اللہ (المتوفیٰ: 168ھ)فرماتے ہیں: ’’جہمیہ نے کتاب اللہ کے بہت سے مقامات کا انکار کیا ہے۔ مثلاً: ’’وہ کہتے ہیں کہ جنت فنا ہوجائے گی۔‘‘ حالانکہ اللہ تبارک وتعالیٰ کا فرمان ہے:\n﴿ إِنَّ هَٰذَا لَرِزۡقُنَا مَا لَهُۥ مِن نَّفَادٍ ﴾ [صٓ: ۵۴]\n’’بلاشبہ یہ ہمارا رزق ہے جو کبھی ختم نہ ہوگا۔‘‘\nتو جو شخص اس بات کا قائل ہے کہ یہ رزق ختم ہوجائے گا، اس نے کفر کیا۔اسی طرح فرمان الٰہی ہے:\n﴿ أُكُلُهَا دَآئِمٌ وَظِلُّهَاۚ ﴾ [الرعد: ۳۵]\n’’اس کے پھل اور اس کا سایہ دائمی ہے۔‘‘\nتو جو شخص یہ کہتا ہے کہ یہ دائمی نہیں ہے تو وہ کفر کرتا ہے۔ فرمان باری تعالیٰ ہے:\n﴿ لَّا مَقۡطُوعَةٍ وَلَا مَمۡنُوعَةٍ ﴾ [الواقعۃ: ۳۳]\n’’جو نہ کبھی ختم ہوں گے اور نہ ان پر کوئی روک ٹوک ہوگی۔‘‘\nتو جو شخص یہ نظریہ رکھتا ہے کہ یہ ختم ہوجائیں گے تو وہ کافر ہے۔ اسی طرح رب تعالیٰ کا ارشاد گرامی ہے:\n﴿ عَطَآءً غَيۡرَ مَجۡذُوذٍ ﴾ [ہود: ۱۰۸]\n’’یہ ایسی بخشش ہوگی جو کبھی منقطع نہ ہوگی۔‘‘\nتو جس کا یہ قول ہے کہ یہ منقطع ہوجائے گی، اس نے کفر کیا۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد (1/130)۔ السنۃ للخلال (5/86)"}],[26,"انہوں نے مزید فرمایا: ’’جہمیہ تک یہ بات پہنچا دو کہ وہ کافر ہیں اور ان کی عورتیں مُطَلَّقہ (طلاق یافتہ) ہیں۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد (1/105 – 106)۔ السنۃ للخلال (5/89)"}],[27,"قتادہ رحمہ اللہ (المتوفیٰ: 113ھ تقریباً)نے فرمانِ باری تعالیٰ:\n﴿ وَكَلِمَتُهُۥٓ أَلۡقَىٰهَآ إِلَىٰ مَرۡيَمَ ﴾ [النساء: ۱۷۱]\n’’اور اللہ کا ایک کلمہ تھا جو اس نے مریم تک پہنچایا۔‘‘\nکے بارے میں فرمایا: ’’اس کلمہ سے لفظ کُنْ مراد ہے۔ جس کے نتیجہ میں عیسیٰ علیہ السلام پیدا ہوئے۔‘‘","",{"k":"تفسیر عبد الرزاق الصنعاني (1/177)۔ تفسیر ابن جریر (6/35)۔ تفسیر ابن أبي حاتم (4/1123)"}],[28,"معدان کہتے ہیں کہ میں نے سفیان ثوری رحمہ اللہ سے فرمان الٰہی:\n﴿ وَهُوَ مَعَكُمۡ أَيۡنَ مَا كُنتُمۡۚ ﴾ [الحدید: ۴]\n’’اور تم جہاں کہیں ہو، وہ تمہارے ساتھ ہے۔‘‘\nکے بارے میں پوچھا تو انہوں نے فرمایا: ’’اس سے اس کا علم مراد ہے۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد (1/307)۔ الشریعۃ للآجري (3/1077 – 1078)۔ الأسماء والصفات للبیہقي (2/341)"}],[29,"ابو ولید طیالسی (المتوفیٰ: 227ھ)کہتے ہیں کہ یحییٰ بن سعید (المتوفیٰ: 198ھ)کے سامنے کسی قوم کا تذکرہ ہوا جو کہتے تھے کہ قرآن مخلوق ہے تو یحییٰ فرمانے لگے: ’’وہ لوگ قرآن کی ان آیات کا جواب دیں گے؟ ﴿ قُلۡ هُوَ ٱللَّهُ أَحَدٌ ﴾ [الإخلاص: ۱] اور ﴿ إِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ ﴾ [طہ: ۱۴]","",{"k":"السنۃ لعبد اللہ بن أحمد (1/159)۔ السنۃ للخلال (7/23 – 24)"}],[30,"عفان (المتوفیٰ: 219ھ تقریباً)کہتے ہیں: ’’جو شخص اس بات کا قائل ہے کہ ﴿ قُلۡ هُوَ ٱللَّهُ أَحَدٌ ﴾ [الإخلاص: ۱] مخلوق ہے، وہ کافر ہے۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد: 1/107 – 108 عن سفیان الثوري رحمہ اللہ، تاريخ بغداد للخطیب: 12/270 – 271"}],[31,"علی بن عبد اللہ المدینی رحمہ اللہ (المتوفیٰ: 234 ھ) فرماتے ہیں: ’’قرآن کلام اللہ ہے۔ جو شخص اس بات کا قائل ہے کہ یہ مخلوق ہے تو وہ کافر ہے۔ اس کے پیچھے نماز نہ پڑھی جائے۔‘‘","",{"k":"اللالکائي (2/264-265)۔ الأسماء والصفات للبیھقي (1/603)۔ تاریخ بغداد للخطیب البغدادي (11/472)"}],[32,"وکیع بن الجراح رحمہ اللہ (المتوفیٰ: 196ھ)فرماتے ہیں: ’’جس نے رؤیت باری تعالیٰ کے بارے میں اسماعیل از قیس از جریر رضی اللہ عنہ از نبی کریم صلی اللہ علیہ وسلم والی روایت کو جھٹلایا، وہ جہمی ہے۔ اس سے دور رہو۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد (1/231، 2/527)"}],[33,"ابو ولید طیالسی فرماتے ہیں: ’’جو شخص اس بات کا قائل ہے کہ قرآن مخلوق ہے، وہ کافر ہے۔ اور جو شخص دل سے اس بات کا پختہ یقین نہیں رکھتا کہ قرآن مخلوق نہیں ہے، وہ دائرہ اسلام سے خارج ہے۔‘‘","",{"k":"السنۃ للخلال (6/92)۔ الإبانۃ لابن بطۃ (2/55)۔ شرح أصول اعتقاد أھل السنۃ لللالکائي (2/259)"}],[34,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’میں نے یہود ونصاریٰ اور مجوسیوں کی باتوں پر غور کیا ہے، لیکن جہمیہ سے بڑھ کر میں نے کسی قوم کو اپنے کفر میں اتنا گمراہ نہیں دیکھا۔ ان لوگوں کے علاوہ، جو جہمیہ کے کفر سے آگاہ نہیں ہیں، جو شخص ان کی تکفیر نہیں کرتا، میں اسے جاہل سمجھتا ہوں۔"],[35,"عبد الرحمن بن عفان کہتے ہیں کہ جس سال مریسی کو مار پڑی تھی، تو سفیان بن عیینہ رحمہ اللہ اپنی مجلس سے غضب ناک ہوکر اٹھے اور فرمایا: ’’قرآن کلام اللہ ہے۔ میں نے بہت سے لوگوں کو دیکھا اور ان کی صحبت میں زندگی گزاری ہے۔ یہ عمرو بن دینار ہیں، یہ ابن منکدر ہیں۔‘‘ یہاں تک کہ انہوں نے منصور، اعمش، مِسْعَر بن کدام کا تذکرہ کیا۔ پھر فرمایا: ’’ان علماء نے فتنہ اعتزال، رفض اور منکرینِ تقدیر کے بارے میں کلام کیا اور ہمیں ان لوگوں سے دور رہنے کا حکم دیا۔ ہم تو بس یہی جانتے ہیں کہ قرآن کلام اللہ ہے۔ جو اس کے علاوہ کسی بات کا قائل ہے، اس پر اللہ کی لعنت ہو۔ یہ قول نصاریٰ کے عقیدہ کے بہت زیادہ مشابہ ہے۔ ایسے لوگوں کے پاس بیٹھو، نہ ان کی باتیں سنو۔‘‘","",{"k":"تاریخ أبي العباس السراج کما في السیر (8/468)۔ حلیۃ الأولیاء وطبقات الأصفیاء لأبي نعیم (7/296)"}],[36,"عبد اللہ بن محمد کہتے ہیں کہ میں نے ابن عیینہ کو مریسی کا تذکرہ کرتے ہوئے سنا، وہ اس کا مذاق اُڑاتے ہوئے کہہ رہے تھے: ’’وہ احمق اور بیوقوف کیا کہتا ہے؟‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد (1/169)۔ السنۃ للخلال (5/109)۔ الشریعۃ للآجري (1/504 – 505)"}],[37,"کہتے ہیں کہ میں نے محمد بن عبید رحمہ اللہ (المتوفیٰ: 204ھ)سے سنا، وہ کہہ رہے تھے کہ یہ خبیث میرے پاس آیا تھا۔ مجھ سے ایک حدیث کے بارے میں پوچھ رہا تھا۔ اگر مجھے وہ حدیث معلوم بھی ہوتی تو اسے نہ بتاتا۔"],[38,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ فرماتے ہیں: ’’اللہ تعالیٰ نے کوئی زمین، آسمان، جنت یا جہنم ایسی نہیں بنائی جو آیت الکرسی سے زیادہ عظمت والی ہو۔‘‘\nسفیان کہتے ہیں: ’’اس کی تفسیر یہ ہے کہ ہر چیز مخلوق ہے، جبکہ اللہ کا کلام اس کی مخلوق سے عظیم ہے کیونکہ اللہ تعالیٰ جب کسی چیز سے کہتے ہیں: ’’ہوجا۔‘‘ تو وہ ہوجاتی ہے۔ لہٰذا اس سے کوئی چیز عظیم نہیں ہوسکتی جس کے ذریعہ تخلیق ہوتی ہے۔ اور قرآن کلام اللہ ہے۔‘‘","",{"k":"سنن سعید بن منصور: 3/953 – 955، فضائل القرآن لأبي عبید القاسم بن سلام: 2/34، 84، رقم: 421، 537، الأسماء والصفات للبیھقي: 2/58۔ ترمذی: 5/161 میں صرف سفیان بن عیینہ کا قول ہے۔"}],[39,"سلّام بن ابی مطیع رحمہ اللہ (المتوفیٰ: 164ھ) کا قول ہے: ’’جہمیہ کافر ہیں۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد (1/105، 2/528)۔ المسائل لأبي داؤد (ص 268)۔ السنۃ للخلال (5/90، 92، 97)"}],[40,"عبد الحمید بن عبد الرحمن الحِمَّانی رحمہ اللہ (المتوفیٰ: 202ھ) کا قول ہے: ’’جہم بن صفوان عظمتوں والے اللہ کا منکر ہے۔‘‘","",{"k":"المسائل لأبي داؤد (ص 269)"}],[41,"وکیع بن الجراح رحمہ اللہ فرماتے ہیں: ’’جہمیہ نےمرجئہ سے جنم لیا ہے۔ جہمیہ کافر ہیں اور مریسی جہمی ہے۔ تم جانتے ہو کہ ان لوگوں نے کس طرح کفر کا ارتکاب کیا ہے؟ وہ کہتے ہیں کہ نجات کےلیے معرفت کافی ہے، جبکہ یہ کفر ہے۔ اور مرجئہ کہتے ہیں کہ ایمان صرف قول کا نام ہے، فعل اس میں شامل نہیں ہے۔ جبکہ یہ قول بدعت ہے۔ لہٰذا جو شخص کہتا ہے کہ قرآن مخلوق ہے، وہ اللہ تعالیٰ کی نبی کریم صلی اللہ علیہ وسلم پر نازل کردہ شریعت کا منکر ہے۔ اس سے توبہ کا مطالبہ کیا جائے۔ اگر نہ کرے تو اس کی گردن اُڑا دی جائے۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد (1/231 – 232)۔ شرح أصول اعتقاد أھل السنۃ لللالکائي (2/317، 4/848)"}],[42,"وکیع بن الجراح رحمہ اللہ فرماتے ہیں: ’’مریسی پر اللہ کی لعنت ہو۔ وہ یہودی یا عیسائی ہے۔‘‘ یہ سن کر ایک شخص نے انہیں بتایا کہ مریسی کا باپ یا دادا یہودی یا عیسائی تھا۔‘‘","",{"k":"التسعینیۃ لابن تیمیۃ (1/372 – 373)۔ الصواعق المرسلۃ لابن القیم (4/1402 – 1403)"}],[43,"وکیع بن الجراح رحمہ اللہ فرماتے ہیں: ’’مریسی اور اس کے پیروکاروں پر اللہ کی لعنت ہو۔ قرآن کلام اللہ ہے۔‘‘ یہ فرما کر وکیع رحمہ اللہ نے اپنے ایک ہاتھ کو دوسرے پر مارا۔ پھر کہنے لگے: ’’بغداد میں مریسی نامی ایک بہت بُرا شخص رہتا ہے۔ اس سے توبہ کروائی جائے۔ اگر توبہ کرلے تو بہتر ہے۔ وگرنہ اسے موت کے گھاٹ اتار دیا جائے۔‘‘"],[44,"یزید بن ہارون رحمہ اللہ کہتے ہیں: ’’میں نے اپنی پوری طاقت کے بقدر اہل بغداد کو اسے قتل کرنے کی ترغیب دی ہے۔ ایک مرتبہ مجھے مریسی کی کوئی بات بتائی گئی جس کی تکلیف میں نے اپنی پشت میں تین (دن/ مہینے / سال) کے بعد بھی محسوس کی۔‘‘","",{"k":"السنۃ للخلال: 5/101 – 104، 111، الرد علی الجہمیۃ للدارمي، ص: 178، ط: الدار السلفیۃ وص: 111، ط: المکتب الإسلامي"}],[45,"علی بن عبد اللہ رحمہ اللہ فرماتے ہیں: ’’مریسی کا مقصد اور غرض وغایت صرف یہی ہے کہ لوگوں کو اپنے کفر میں مبتلا کردے۔‘‘"],[46,"عبید اللہ بن عائشہ رحمہ اللہ (المتوفیٰ: 228 ھ) کا قول ہے: ’’جو شخص قرآن کے مخلوق ہونے کا قائل ہے، اس کے پیچھے نماز پڑھی جائے، نہ اس کی عزت کی جائے۔ اگر کوئی شخص اپنے آپ کو بچانے کےلیے ان کے پیچھے نماز پڑھ لے اور تکبیر کہہ دے تو خیر ہے، وگرنہ اس سے اجتناب ہی مجھے زیادہ محبوب ہے۔ کیونکہ وہ کہتے ہیں: ’’چیز کوئی چیز نہیں ہے۔ اور اللہ بھی کوئی چیز نہیں ہے۔‘‘"],[47,"سلیمان بن داؤد ہاشمی (المتوفیٰ: 219 ھ)اور سہل بن مزاحم کا قول ہے: ’’جس نے قرآن کے مخلوق ہونے کے قائل کے پیچھے نماز پڑھی، اسے چاہیے کہ اپنی نماز دہرائے۔‘‘"],[48,"عبد الرحمن بن مہدی رحمہ اللہ (المتوفیٰ: 198ھ)نے یحییٰ بن سعید سے کہا: ’’اگر میرے اور کسی جہمی کے درمیان رشتہ داری ہوتی تو میں اس کی وراثت میں سے ذرہ برابر چیز لینا بھی حلال نہ سمجھتا۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد (1/121)۔ الإبانۃ لابن بطۃ (2/81)۔ شرح أصول اعتقاد أھل السنۃ لللالکائي (2/320)"}],[49,"ابن مہدی رحمہ اللہ مزید فرماتے ہیں: ’’اگر میں کسی شخص کو پُل پر دیکھوں جو قرآن کے مخلوق ہونے کا قائل ہو اور میرے ہاتھ میں تلوار ہو، تو میں ضرور اس کا سر تن سے جدا کردوں گا۔‘‘","",{"k":"مسائل أحمد لأبي داؤد (ص 262)۔ السنۃ لعبد اللہ بن أحمد (1/119 – 120)۔ الإبانۃ لابن بطۃ (2/48)"}],[50,"یزید بن ہارون رحمہ اللہ فرماتے ہیں: ’’مریسی مانی سے زیادہ نقصان دہ ہے۔‘‘","",{"k":"مانی سے مراد مانی بن فاتک بن حکیم ہے جو کفر وضلالت میں ضرب المثل تھا۔ یہ عیسی علیہ السلام کے بعد سابور بن ارد شیر کے زمانہ میں پیدا ہوا۔ اس نے مجوسیت اور عیسائیت کا ملغوبہ تیار کرکے ایک نیا دین گھڑا۔ اس کے عقائد اور نظریات بہت عجیب وغریب تھے۔ بہرام بن سابور نے اسے قتل کیا۔ سلف کے ہاں یہ شخص کفر وبدعقیدگی کی مثال کے طور پر مشہور تھا۔ دیکھیے: الملل والنحل للشھرستاني: 2/49، الفَرْق بین الفِرَق للبغدادي، ص: 271، الرد علی الجہمیۃ للدارمي، ص: 176، شرح أصول اعتقاد أھل السنۃ لللالکائي: 2/361"}],[51,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’میں کسی جہمی یا رافضی کے پیچھے نماز پڑھوں یا کسی یہودی یا عیسائی کے پیچھے، مجھے کوئی پروا نہیں۔ (مطلب یہ ہے کہ جس طرح یہود ونصاریٰ کے پیچھے نماز نہیں ہوتی، اسی طرح جہمیوں اور رافضیوں کے پیچھے بھی نہیں ہوتی۔) نہ انہیں سلام کیا جائے، نہ ان کی تیمار داری کےلیے جایا جائے، نہ ان سے نکاح کیا یا کرایا جائے، نہ ان کے جنازوں میں شرکت کی جائے اور نہ ہی ان کے ذبح کردہ جانور کو کھایا جائے۔‘‘"],[52,"عبد الرحمن بن مہدی رحمہ اللہ فرماتے ہیں: ’’جہمیہ اور روافض (اسلام سے الگ) دو ملتیں ہیں۔‘‘"],[53,"ابو عبید قاسم بن سَلَّام سے کسی نے کہا: ’’مریسی سے فرمان الٰہی:\n﴿ إِنَّمَا قَوۡلُنَا لِشَيۡءٍ إِذَآ أَرَدۡنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ ﴾ [النحل: ۴۰]\n’’ہم تو جب کسی چیز کا ارادہ کر لیتے ہیں تو اسے بس اتنا ہی کہہ دیتے ہیں کہ ’’ہوجا‘‘\nتو وہ ہوجاتی ہے۔‘‘ کے تحت اشیاء کی تخلیق کی ابتداء کے بارے میں پوچھا گیا (کہ اس آیت سے تو پتہ چلتا ہے کہ تمام اشیاء کی تخلیق اللہ تعالیٰ کے حکم سے ہوئی ہے) تو اس نے کہا: ’’یہ پورا کلام صلہ ہے۔‘‘ اس کے کہنے کا مطلب ہے کہ «اَنْ يَّقُوْلَ» صلہ ہے جیسے کہتے ہیں: ’’آسمان نے کہا اور برس پڑا۔‘‘ یا جیسے محاورہ ہے کہ ’’دیوار نے کہا اور جھک گئی۔‘‘ جیسے فرمان باری تعالیٰ ہے:\n﴿ جِدَارًا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُۥۖ ﴾ [الکھف: ۷۷]\n’’موسیٰ علیہ السلام نے دیوار دیکھی جو گرا چاہتی تھی۔ (خضر نے) اس دیوار کو پھر سے قائم کردیا۔ ‘‘\nحالانکہ دیوار کے اندر ارادہ نہیں ہوتا۔ لہٰذا فرمان الٰہی: ﴿ إِذَآ أَرَدۡنَٰهُ ﴾ کا مطلب یہ ہے کہ ہم نے اسے بنایا اور وہ بن گئی۔ مریسی کے ہاں اس بات کا اس سے زیادہ اور کوئی جواب ہو بھی نہیں سکتا کہ ’’اللہ تعالیٰ کلام نہیں کرتا۔‘‘"],[54,"ابو عبید قاسم بن سلّام فرماتے ہیں: ’’جہاں تک اس کے فرمان الٰہی: ﴿ إِذَآ أَرَدۡنَٰهُ أَن نَّقُولَ لَهُۥ ﴾ کو ’’آسمان نے کہا اور برس پڑا۔‘‘ اور’’دیوار نے کہا اور جھک گئی۔‘‘ جیسے محاوروں سے تشبیہ دینے کا تعلق ہے تو حقیقت میں یہ آیت ان محاوروں کے مشابہ نہیں ہے۔ دراصل یہ ایک مغالطہ ہے جو اس نے دینا چاہا ہے۔ کیونکہ جب آپ کہتے ہیں کہ ’’آسمان نے کہا‘‘ اور پھر آپ خاموش ہوجاتے ہیں تو تب تک آسمان کے کہنے کا معنیٰ معلوم نہیں ہوتا جب تک آپ یہ نہ کہیں کہ ’’وہ برس پڑا۔‘‘ اسی طرح جب آپ کہتے ہیں کہ ’’دیوار نے ارادہ کیا‘‘ پھر آپ لفظ ارادہ کی وضاحت نہیں کرتے تو اس کا معنیٰ معلوم نہیں ہوتا۔ لیکن جب آپ کہتے ہیں کہ ’’اللہ تعالیٰ نے فرمایا‘‘ تو یہاں یہ کہنا کہ ’’فرمایا‘‘ کافی ہے۔ اس کے ساتھ کسی اور چیز کی ضرورت نہیں ہے جو یہ بتائے کہ ’’فرمایا‘‘ کا کیا مطلب ہے۔ جیسا کہ آپ نے ’’دیوار نے کہا اور جھک گئی‘‘ سے دلیل لی ہے۔ وگرنہ ’’دیوار نے کہا‘‘ کا کوئی معنیٰ نہیں بنتا۔جو شخص اس بات کا قائل ہے تو اس کے کفر سے زیادہ اور کوئی کفر نہیں ہوسکتا۔ جو شخص اس بات کا قائل ہے، وہ اللہ کے بارے میں ایسی بات کہتا ہے جو یہود ونصاریٰ نے بھی نہیں کہی۔ خالق کے بارے میں اس کا نظریہ معطلہ والا ہے۔‘‘"],[55,"علی بن مدینی رحمہ اللہ فرماتے ہیں کہ میں نے بصرہ میں بشر بن مفضل رحمہ اللہ (المتوفیٰ: 186ھ)کو ابن خالویہ جہمی کا تذکرہ کرتے ہوئے سنا۔ بشر نے کہا: ’’وہ کافر ہے۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد: 1/128 – 129۔ اس میں جہمی کا نام ابن خلوبا مذکور ہے۔ نیز دیکھیے: شرح أصول اعتقاد أھل السنۃ لللالکائي: 2/258"}],[56,"وکیع بن الجراح رحمہ اللہ سے مثنّی انماطی کے بارے میں پوچھا گیا تو انہوں نے فرمایا: ’’وہ کافر ہے۔‘‘"],[57,"عبد اللہ بن داؤد رحمہ اللہ (المتوفیٰ: 213 ھ)فرماتے ہیں: ’’اگر میں مثنی انماطی کے معاملہ میں ذرہ برابر بھی اختیار رکھتا تو اس کی زبان گدی سے کھینچ لیتا۔ وہ جہمی تھا۔‘‘"],[58,"سلیمان بن داؤد ہاشمی رحمہ اللہ فرماتے ہیں: ’’جو شخص قرآن کے مخلوق ہونے کا قائل ہے، وہ کافر ہے۔ اگر ان کے نظریہ کے مطابق قرآن واقعتاً مخلوق ہے تو پھر فرعون\n﴿ أَنَا۠ رَبُّكُمُ ٱلۡأَعۡلَىٰ ﴾ [النازعات: ۲۴]\n’’میں ہی تمہارا سب سے بڑا رب ہوں۔‘‘\nکہنے کی وجہ سے ابدی جہنمی ہونے کا مستحق کیوں قرار پایا؟ ان کا نظریہ ہے کہ قرآن مخلوق ہے جبکہ قرآن کہتا ہے:\n﴿ إِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدۡنِي ﴾ [طہ: ۱۴]\n’’بلاشبہ میں ہی اللہ ہوں، میرے سوا کوئی الٰہ نہیں۔ لہٰذا میری ہی عبادت کرو۔‘‘\nیہ وہی دعویٰ ہے جو فرعون نے کیا تھا۔ پھر قرآن کی بجائے فرعون ابدی جہنمی ہونے کا مستحق کیوں ہے جبکہ جہمیہ کے نزدیک دونوں مخلوق ہیں؟‘‘"],[59,"جب یہ قول ابو عبید کو بتایا گیا تو انہیں بہت اچھا لگا اور انہوں نے اس کی تحسین کی۔","",{"k":"مجموع الفتاوی لابن تیمیۃ (12/509 – 510)"}],[60,"احمد بن محمد رحمہ اللہ (المتوفیٰ: 217ھ)فرماتے ہیں: ’’مجھ پر یہ واضح ہوچکا ہے کہ یہ لوگ (یعنی جہمیہ) کافر ہیں۔‘‘"],[61,"فضیل بن عِیاض رحمہ اللہ (المتوفیٰ: 187ھ) فرماتے ہیں: ’’جب کوئی جہمی آپ سے کہے کہ میں اس رب کا انکار کرتا ہوں جو اپنی جگہ سے ہٹ جاتا ہے تو آپ اسے جواب دیں کہ میں اس رب پر ایمان لاتا ہوں جو اپنی مرضی کے مطابق جو چاہتا ہے، کر گزرتا ہے۔‘‘","",{"k":"شرح أصول اعتقاد أھل السنۃ لللالکائي (2/453)۔ الإبانۃ لابن بطۃ (3/204)"}],[62,"سفیان بن عیینہ رحمہ اللہ فرماتے ہیں: ’’میں نے ابن ادریس کو بچوں کے پاس کھڑے ہوئے دیکھا تو پوچھا: ’’ابو محمد! آپ یہاں کیا کررہے ہیں؟‘‘ وہ کہنے لگے: ’’میں اس بچے کے منہ سے اپنے رب کا کلام سن رہا ہوں۔‘‘"],[63,"یزید بن ہارون رحمہ اللہ جہمیہ سے خبردار کرتے ہوئے فرماتے ہیں: ’’جو شخص یہ نظریہ رکھتا ہے کہ رحمن عرش پر اس صورت کے برخلاف مستوی ہے جیسا کہ عوام الناس عقیدہ رکھتے ہیں، تو وہ جہمی ہے۔ محمد شیبانی بھی جہمی ہے۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد (1/123)۔ المسائل لأبي داؤد (ص 268)۔ الإبانۃ لابن بطۃ (3/164)"}],[64,"سلیمان التیمی رحمہ اللہ (المتوفیٰ: 143ھ) فرماتے ہیں: ’’اگر مجھ سے اللہ تبارک وتعالیٰ کے بارے میں پوچھا جائے کہ وہ کہاں ہے؟ تو میں کہوں گا: ’’وہ آسمان پر ہے۔‘‘ اگر وہ پوچھے کہ آسمان سے پہلے اس کا عرش کہاں تھا؟ تو میں کہوں گا: ’’پانی پر۔‘‘ اگر معترض پھر پوچھے کہ پانی سے پہلے اس کا عرش کہاں تھا؟ تو میں کہوں گا: ’’مجھے علم نہیں۔‘‘","",{"k":"شرح أصول اعتقاد أھل السنۃ لللالکائي (3/401)۔ إثبات صفۃ العلو لابن قدامۃ (ص 114)"}],[65,"امام بخاری رحمہ اللہ فرماتے ہیں کہ ان کے لاعلمی کا اظہار کرنے کی وجہ یہ ہے کہ اللہ تعالیٰ نے فرمایا ہے:\n﴿ وَلَا يُحِيطُونَ بِشَيۡءٍ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ ﴾ [البقرۃ: ۲۵۵]\n’’یہ لوگ اللہ کے علم میں سے کسی چیز کا بھی ادراک نہیں کر سکتے مگر اتنا ہی جتنا وہ خود چاہے۔‘‘\nیعنی جتنا اللہ نے بیان کردیا ہے، (اتنا ہی علم ہے، اس سے زیادہ نہیں۔)"],[66,"سفیان بن عیینہ، معاذ بن معاذ، حجاج بن محمد، یزید بن ہارون، ہاشم بن قاسم، ربیع بن نافع حَلَبی، محمد بن یوسف، عاصم بن عاصم، یحییٰ بن یحییٰ اور دیگر اہل علم کا کہنا ہے کہ ’’جو شخص قرآن کے مخلوق ہونے کا قائل ہے، وہ کافر ہے۔‘‘","",{"k":"شرح أصول اعتقاد أھل السنۃ لللالکائي (2/272 – 312)۔ السنۃ لعبد اللہ بن أحمد (1/102)۔ السنۃ للخلال (6/9 – 101)"}],[67,"محمد بن یوسف رحمہ اللہ فرماتے ہیں: ’’جو شخص اس بات کا قائل ہے کہ اللہ تعالیٰ اپنے عرش پر نہیں ہے، وہ کافر ہے۔ اسی طرح جو شخص یہ نظریہ رکھتا ہے کہ اللہ تعالیٰ نے موسیٰ علیہ السلام سے کلام نہیں کیا، وہ بھی کافر ہے۔‘‘"],[68,"احمد بن یونس رحمہ اللہ (المتوفیٰ: 227ھ) سے پوچھا گیا: ’’آپ نے بہت سے لوگوں سے ملاقات کی ہے، کیا ان میں سے کسی ایک کو بھی یہ کہتے ہوئے سنا ہے کہ قرآن مخلوق ہے؟‘‘ وہ کہنے لگے: ’’یہ بات تو شیطان ہی کرتا ہے۔ جو شخص اس کا قائل ہے، وہ جہمی ہے اور جہمی کافر ہے۔‘‘"],[69,"وکیع بن الجراح رحمہ اللہ فرماتے ہیں: ’’جہمیہ کی بات ’’قرآن مخلوق ہے۔‘‘ کو ہلکی بات نہ سمجھو، کیونکہ یہ بہت ہی بری بات ہے۔ یہ لوگ معطلہ والا مذہب رکھتے ہیں۔‘‘","",{"k":"الأسماء والصفات للبیھقي (1/616)"}],[70,"حسن بن موسیٰ اشیب رحمہ اللہ (المتوفیٰ: 209ھ) نے ایک مرتبہ جہمیہ کا تذکرہ کیا اور انہیں برا بھلا کہا۔ پھر کہنے لگے: ’’زندیقوں کے ایک سرغنہ شَمْعلہ کو مہدی کے پاس لے جایا گیا۔ مہدی نے کہا: ’’مجھے اپنے ساتھیوں کے نام بتاؤ۔‘‘ اس نے کہا: ’’میرے ساتھیوں کی تعداد شمار سے بھی زیادہ ہے۔‘‘ مہدی نے پوچھا: ’’بتاؤ وہ کون لوگ ہیں؟‘‘اس نے کہا: ’’اسلام کی طرف منسوب دو فرقوں جہمیہ اور قدریہ کے لوگ۔ جہمی جب غلو کرتا ہے تو کہتا ہے کہ وہ وہاں (اشیب نے آسمان کی طرف اشارہ کیا) کوئی نہیں ہے۔ اور قدری جب غلو کرتا ہے تو کہتا ہے کہ خدا دو ہیں۔ ایک خالقِ خیر اور دوسرا خالقِ شر۔‘‘ یہ سن کر مہدی نے اس کی گردن اتارنے اور مال بحق سرکار ضبط کرنے کا حکم دیا، جس پر عمل درآمد کیا گیا۔"],[71,"ابو نعیم شجاع بلخی (المتوفیٰ: 190ھ) فرماتے ہیں: ’’اہل مرو میں سے ایک شخص جہم کا دوست تھا۔ پھر اس نے اس سے تعلق قطع کرلیا اور اسے دھتکار دیا۔ کسی نے اس سے پوچھا کہ تم نے جہم کو کیوں دھتکارا؟ وہ کہنے لگا: ’’اس نے ایسی بات کی ہے کہ جسے برداشت نہیں کیا جاسکتا۔ میں نے ایک دن اس کے سامنے ایک آیت پڑھی تو کہنے لگا: ’’محمد صلی اللہ علیہ وسلم نے جب ایسا فرمایا تو وہ کس قدر چالاک تھے! (نعوذ باللہ) میں نے برداشت کیا۔ پھر اس نے سورت طٰہٰ کی تلاوت شروع کی، جب آیت:\n﴿ ٱلرَّحۡمَٰنُ عَلَى ٱلۡعَرۡشِ ٱسۡتَوَىٰ ﴾ [طہ: ۵]\n’’وہ بےحد رحم والا عرش پر بلند ہوا۔‘‘\nپر پہنچا تو کہنے لگا: ’’اللہ کی قسم! اگر میرا بس چلتا تو اس آیت کو کھرچ کر قرآن سے نکال دیتا۔‘‘ میں نے اسے بھی برداشت کیا۔ پھر اس نے سورۃ القصص کی تلاوت شروع کی۔ جب موسیٰ علیہ السلام کا تذکرہ شروع ہوا تو کہنے لگا: ’’یہ کیا طریقہ ہے؟ ایک جگہ ان کا قصہ بیان کرنا شروع کیا تو ادھورا بیان کیا۔ پھر یہاں بیان کرنا شروع کیا تو یہاں بھی ادھورا چھوڑ دیا۔‘‘ پھر اس نے اپنی گود میں رکھے ہوئے قرآن کو ٹانگ مار کر نیچے پھینک دیا۔یہ دیکھ کر مجھ سے برداشت نہ ہوسکا اور میں اس پر چڑھ دوڑا۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد (1/167)۔ الإبانۃ لابن بطۃ (2/92)۔ العلو للذھبي (ص 114)"}],[72,"یحییٰ بن ایوب کہتے ہیں کہ ایک دن ہم مروان بن معاویہ فزاری رحمہ اللہ (المتوفیٰ: 193ھ) کے پاس بیٹھے ہوئے تھے۔ کسی آدمی نے ان سے رؤیت باری تعالیٰ والی حدیث کے متعلق پوچھا تو انہوں نے اس کے سامنے وہ حدیث بیان نہ کی۔ وہ آدمی کہنے لگا: ’’اگر آپ میرے سامنے وہ حدیث بیان نہیں کرتے تو اس کا مطلب ہے کہ آپ جہمی ہیں۔‘‘ مروان کہنے لگے: ’’تم مجھے جہمی کہہ رہے ہو، جبکہ جہم وہ شخص ہے جس نے چالیس دن ایسے بھی گزارے تھے کہ ان میں وہ اپنے رب کو جانتا ہی نہ تھا۔‘‘","",{"k":"السنۃ للخلال: 5/87 مختصرا، الإبانۃ لابن بطۃ: 2/93"}],[73,"عبد اللہ بن مبارک رحمہ اللہ فرماتے ہیں: ’’جہمیہ کے علاوہ ہر قوم اپنے معبود کو پہچانتی ہے۔‘‘"],[74,"ابو جعفر کہتے ہیں کہ ایک مرتبہ یزید بن ہارون نے اپنی سند سے رؤیت باری تعالیٰ والی حدیث ہمیں سنائی اور پھر فرمانے لگے: ’’جو شخص اس حدیث کو جھٹلاتا ہے، وہ اللہ اور اس کے رسول صلی اللہ علیہ وسلم سے بیزار ہے۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد (1/232)"}],[75,"یزید بن ہارون رحمہ اللہ نے ایک مرتبہ ابو بکر الاصم اور مریسی کا تذکرہ کیا تو فرمایا: ’’اللہ کی قسم! یہ دونوں زندیق، الرحمٰن کے منکر اور واجب القتل ہیں۔‘‘","",{"k":"المسائل لأبي داؤد (ص 270)۔ السنۃ للخلال (5/110)۔ الإبانۃ لابن بطۃ (2/101)"}],[76,"عبد الرحمن بن مہدی رحمہ اللہ فرماتے ہیں: ’’جس شخص کا یہ نظریہ ہے کہ اللہ تعالیٰ نے موسیٰ علیہ السلام سے کلام نہیں کیا، اس سے توبہ طلب کی جائے۔ اگر اپنے اس نظریہ سے رجوع کرلے تو ٹھیک، وگرنہ اس کی گردن اتار دی جائے۔‘‘","",{"k":"المسائل لأبي داؤد (ص 262)۔ السنۃ لعبد اللہ بن أحمد (1/119)۔ الأسماء والصفات للبیھقي (1/607 – 608)"}],[77,"امام مالک رحمہ اللہ (المتوفیٰ: 179ھ) فرماتے ہیں: ’’قرآن کلام اللہ ہے۔‘‘"],[78,"یزید بن ہارون رحمہ اللہ فرماتے ہیں: ’’اس ذات کی قسم جس کے علاوہ کوئی معبود ِ حقیقی نہیں ہے! جہمیہ زندیق یا مشرک ہیں۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد (1/122)۔ الإبانۃ لابن بطۃ (2/100)۔ الشریعۃ للآجري (1/503)"}],[79,"عبد اللہ بن ادریس رحمہ اللہ سے بدعتیوں کے پیچھے نماز پڑھنے کے متعلق پوچھا گیا تو انہوں نے فرمایا: ’’جب اچھا یا قابل اعتماد آدمی موجود ہوتو اس کے پیچھے نماز پڑھو۔‘‘ میں نے پوچھا: ’’جہمیہ کے پیچھے نماز پڑھنا کیسا ہے؟‘‘ فرمانے لگے: ’’وہ بدعتی نہیں، بلکہ حربی ہیں۔ ان لوگوں کے پیچھے نماز پڑھی جائے اور نہ ان سے نکاح کیا اور کرایا جائے۔ ان پر توبہ کرنا لازم ہے۔‘‘","",{"k":"الأسماء والصفات للبیھقي (1/609)"}],[80,"حفص بن غیاث رحمہ اللہ (المتوفیٰ: 194ھ) سے بدعتیوں کے بارے میں پوچھا گیا تو انہوں نے بھی وہی بات کی جو عبد اللہ بن ادریس نے کی تھی۔ کسی نے پوچھا: ’’جہمیہ کے بارے میں آپ کیا کہتے ہیں؟‘‘ کہنے لگے: ’’میں انہیں نہیں جانتا۔‘‘ بتایا گیا کہ وہ ایسے لوگ ہیں جو قرآن کے مخلوق ہونے کے قائل ہیں۔ تو کہنے لگے: ’’ایسا نہیں ہوسکتا۔ اللہ تمہیں جزائے خیر دے۔ تم نے میرے سامنے ایسی بات کردی ہے جو میں نے پہلے کبھی نہیں سنی تھی۔‘‘ میں نے کہا:’’واقعتاً وہ اسی بات کے قائل ہیں۔‘‘ یہ سن کر حفص بن غیاث کہنے لگے: ’’ایسے لوگوں سے رشتہ ناتہ نہ کیا جائے اور نہ ان کی گواہی مقبول ہے۔‘‘","",{"k":"الإبانۃ لابن بطۃ (2/31)۔ الأسماء والصفات للبیھقي (1/609 – 610)"}],[81,"سفیان بن عیینہ رحمہ اللہ سے پوچھا گیا تو انہوں نے بھی یہی جواب دیا۔"],[82,"وہ کہتے ہیں کہ پھر میں وکیع بن الجراح رحمہ اللہ کے پاس گیا تو میں نے انہیں سب سے بڑھ کر جہمیہ کے بارے میں معلومات رکھنے والا پایا۔ وہ فرمانے لگے کہ جہمیہ فلاں وجہ سے کافر ہیں اور فلاں وجہ سے بھی کافر ہیں۔ یہاں تک کہ انہوں نے بہت سی وجوہات سے ان کا کافر ہونا ثابت فرمایا۔","",{"k":"السنۃ للخلال (7/32 – 33)۔ الأسماء والصفات للبیھقي (1/609 – 610)"}],[83,"وکیع بن الجراح رحمہ اللہ فرماتے ہیں: ’’روافض قدریہ سے بُرے ہیں اور حروریہ (خوارج) ان دونوں سے برے ہیں۔ جہمیہ ان سب سے برے ہیں۔ فرمان الٰہی ہے:\n﴿ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكۡلِيمًا ﴾ [النساء: ۱۶۴]\n’’اور اللہ تعالیٰ نے موسیٰ علیہ السلام سے بول کر کلام کیا۔‘‘\nجبکہ یہ لوگ اس بات کے قائل ہیں کہ اللہ تعالیٰ نے بات نہیں کی۔ اس کے علاوہ ان کا یہ بھی نظریہ ہے کہ ایمان صرف دل کی معرفت کا نام ہے۔‘‘","",{"k":"السنۃ للخلال (1773)"}],[84,"حسن بن ربیع رحمہ اللہ (المتوفیٰ: 221ھ) فرماتے ہیں: ’’(خلق قرآن والی) ایک بات ہے جو انہوں نے گھڑ لی ہے۔مجھ سے اس حوالہ سےسے ایک حدیث پوچھی گئی تو انہوں نے میرے سامنے اس کی وضاحت کی۔‘‘"],[85,"معتمر بن سلیمان رحمہ اللہ (المتوفیٰ: 187ھ) قرآن کے مخلوق ہونے کے قائلین پر اعتراض کرتے تھے اور انہیں بدعتی قرار دیتے تھے۔"],[86,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’منقول ہے کہ سَلْم بن اَحْوز وہ شخص ہے جس نے جہم کو قتل کیا تھا۔‘‘","",{"k":"السنۃ لعبد اللہ بن أحمد (1/167)۔ الإبانۃ لابن بطۃ (2/94)۔ شرح أصول اعتقاد أھل السنۃ لللالکائي (3/379، 381)"}],[87,"سیدنا جابر بن عبد اللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم موقف (عرفات) میں اپنے آپ کو لوگوں کے سامنے پیش کرتے ہوئے کہتے تھے:’’ہے کوئی جو مجھے اپنی قوم میں لے چلے؟ کیونکہ قریش نے مجھے اپنے رب کے کلام(قرآن) کی تبلیغ سے روک دیا ہے۔‘‘","",{"k":"سنن الترمذي (2925)۔ سنن أبي داؤد (4734)۔ سنن ابن ماجہ (201)"}],[88,"سیدنا انس بن مالک رضی اللہ عنہ فرماتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم کو خانہ کعبہ سے معراج کروایا گیا تو آپ صلی اللہ علیہ وسلم نے دیکھا کہ موسیٰ علیہ السلام اللہ تعالیٰ سے ہم کلامی کا شرف حاصل ہونے کی وجہ سے ساتویں آسمان پر ہیں۔‘‘","",{"k":"صحیح البخاري (7517)۔ صحیح مسلم (481)"}],[89,"سیدنا ابو ذر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ کا ارشاد گرامی ہے: ’’میرا کچھ عطاء کرنا صرف کہہ دینا ہے، اور میرا عذاب بھی صرف کہہ دینا ہے۔جب میں کسی چیز کا ارادہ کرتا ہوں تو اسے کہتا ہوں: ”ہو جا“ بس وہ ہو جاتی ہے۔‘‘","",{"k":"سنن الترمذي (2495)۔ سنن ابن ماجہ (4257)"}],[90,"سیدنا عبد اللہ بن انیس رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”اللہ بندوں کو روزِ قیامت جمع کرے گا اور ایسی آواز کے ذریعہ ان کو پکارے گا جسے دور والے اسی طرح سنیں گے جس طرح نزدیک والے سنیں گے:’’ میں بادشاہ ہوں۔ ہر ایک کے اعمال کا بدلہ دینے والا ہوں۔کسی جنتی کے لائق نہیں ہے کہ وہ جنت میں داخل ہو جبکہ جہنمیوں میں سے کوئی شخص اس سے کسی ظلم کی تلافی کا مطالبہ کرنے والا ہو۔“","",{"k":"الأدب المفرد للبخاري (790)۔ المسند للإمام أحمد (3/495)۔ السنۃ لابن أبي عاصم (1/225)۔ المستدرك للحاکم (2/437 – 438)"}],[91,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’جب اللہ تعالیٰ آسمان پر کسی بات کا فیصلہ کرتا ہے تو فرشتے اللہ تعالیٰ کے فیصلہ کو سن کر جھکتے ہوئے اور عاجزی کرتے ہوئے اپنے پَر پھڑپھڑاتے ہیں۔ اللہ کا فرمان انہیں اس طرح سنائی دیتا ہے جیسے صاف چکنے پتھر پر زنجیر چلانے سے آواز پیدا ہوتی ہے۔ پھر جب ان کے دلوں سے گھبراہٹ دور ہو جاتی ہے تو وہ آپس میں پوچھتے ہیں کہ تمہارے رب نے کیا فرمایا؟ وہ کہتے ہیں کہ حق بات کا حکم فرمایا اور وہ بہت اونچا اور سب سے بڑا ہے۔‘‘","",{"k":"صحیح البخاري (4701، 4800، 7481)"}],[92,"سیدنا عبد اللہ بن عباس، عبد اللہ بن مسعود رضی اللہ عنہما اور دیگر اہل علم بھی اسی بات (یعنی فرشتوں کے آوازِ الٰہی کو سن کر پَر پھڑپھڑانے)کے قائل ہیں۔"],[93,"سیدنا خباب بن ارت رضی اللہ عنہ فرماتے ہیں: ’’جس قدر طاقت رکھتے ہو، اللہ تعالیٰ کا قرب حاصل کرتے جاؤ۔ تم جن چیزوں کے ذریعہ بھی اس کا قرب حاصل کرسکتے ہو، ان میں سے اللہ تعالیٰ کو اپنا کلام سب سے زیادہ محبوب ہے۔ ‘‘","",{"k":"فضائل القرآن لأبي عبید القاسم بن سلام (47)۔ الزھد لابن أبي عاصم (ص 202)۔ الزھد للإمام أحمد (ص 35)"}],[94,"سیدنا نِیار بن مُکرِم اسلمی رضی اللہ عنہ بیان کرتے ہیں کہ جب سورت روم کی ابتدائی آیات نازل ہوئیں تو سیدنا ابو بکر رضی اللہ عنہ بلند آواز سے یہ کہتے ہوئے نکلے: ’’میرے رب کا کلام ہے۔ میرے رب کا کلام ہے۔‘‘","",{"k":"سنن الترمذي (3194)۔ السنۃ لعبد اللہ بن أحمد (1/143)۔ التوحید لابن خزیمۃ (1/404 – 405)"}],[95,"سیدہ اسماء بنت ابی بکر رضی اللہ عنہا جب قرآن سنتیں تو فرماتیں: ’’میرے رب کا کلام ہے۔ میرے رب کا کلام ہے۔‘‘","",{"k":"السنۃ للخلال: 7/56 – 57 بسند صحیح"}],[96,"ابو عبد الرحمن سُلَمی رحمہ اللہ فرماتے تھے: ’’قرآن کو دیگر تمام کلاموں پر ایسے ہی فضیلت حاصل ہے جیسے رب تعالیٰ کو اپنی مخلوق پر فضیلت حاصل ہے۔‘‘","",{"k":"الرد علی الجہمیۃ للدارمي (341)۔ الإبانۃ لابن بطۃ (1/251)۔ شرح أصول اعتقاد أھل السنۃ لللالکائي (2/338 – 339)"}],[97,"سیدنا ابو ذر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے پوچھا: ’’یا رسول اللہ! پہلے نبی کون تھے؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’آدم علیہ السلام۔‘‘ میں نے کہا: ’’یقیناً وہ نبی تھے۔‘‘ فرمایا: ’’ہاں، اللہ تعالیٰ ان سے کلام کرتے تھے۔‘‘","",{"k":"المسند للإمام أحمد (5/178 – 179)۔ المسند للطیالسي (478)۔ الرد علی الجہمیۃ للدارمي (298)"}],[98,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ فرماتے ہیں: ’’جب اللہ تعالیٰ نے موسیٰ علیہ السلام سے کلام کیا تو آواز آسمان سے آرہی تھی اور اللہ تعالیٰ آسمان پر تھے۔‘‘","",{"k":"تفسیر ابن أبي حاتم (9/2974)"}],[99,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ فرماتے تھے: ’’سب سے سچی بات اللہ عزوجل کا کلام ہے۔‘‘","",{"k":"مصنف ابن أبي شیبۃ (13/295)۔ المدخل إلی السنن الکبری للبیھقي (1/426)۔ الاعتقاد للبیھقي (1/104)"}],[100,"سیدنا ابو بکر صدیق رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے شفاعت کا تذکرہ کرتے ہوئے فرمایا: ’’نوح علیہ السلام فرمائیں گے: ’’ابراہیم علیہ السلام کے پاس چلے جاؤ کیونکہ اللہ تعالیٰ نے انہیں خلیل بنایا تھا۔‘‘ لوگ ابراہیم علیہ السلام کے پاس جائیں گے۔ وہ فرمائیں گے: ’’موسیٰ علیہ السلام کے پاس چلے جاؤ کیونکہ اللہ تعالیٰ نے ان سے بول کر کلام کیا تھا۔‘‘","",{"k":"المسند للإمام أحمد (1/4 – 5)۔ مسند أبي عوانۃ (1/151)۔ السنۃ لابن أبي عاصم (812)"}],[101,"سیدنا ابو ہریرہ اور عبد اللہ بن عمر رضی اللہ عنہما بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’بلا شبہ اللہ تعالیٰ نے موسیٰ علیہ السلام کو اپنی ہم کلامی اور اپنی رسالت کا شرف بخشنے کےلیے منتخب فرمایا تھا۔‘‘","",{"k":"صحیح البخاري (4712)، صحیح مسلم (194) عن أبي ھریرۃ رضی اللہ عنہ"}],[102,"سیدنا عدی بن حاتم رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے ہر شخص سے تمہارا رب اس طرح بات کرے گا کہ تمہارے اور اس کے درمیان کوئی ترجمان نہیں ہو گا۔ بندہ اپنے دائیں طرف دیکھے گا تو اسے اپنے اعمال کے سوا اور کچھ نظر نہیں آئے گا۔ وہ اپنے بائیں طرف دیکھے گا تو اسے اپنے اعمال کے سوا کچھ نظر نہیں آئے گا۔ پھر اپنے سامنے دیکھے گا تو اپنے سامنے جہنم کے سوا اور کوئی چیز نہ دیکھے گا۔ اس لیے جہنم سے بچو، خواہ کھجور کے ایک ٹکڑے ہی کے ذریعہ ہو سکے۔خواہ ایک اچھی بات ہی کے ذریعہ ہو۔‘‘","",{"k":"صحیح البخاري (1413، 7512)۔ صحیح مسلم (1016)"}],[103,"سیدنا جابر بن عبد اللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کیا میں تمہیں اس چیز کی بشارت نہ دوں جسے اللہ تعالیٰ نے تمہارے والد محترم سے ملاقات کے وقت کہا؟“ اللہ تعالیٰ نے تمہارے والد سے بغیر پردہ کےآمنے سامنے بات کی، اور اس سے کہا: ’’اے میرے بندے! مجھ سے کسی چیز کے حاصل کرنے کی تمنا و آرزو کر۔‘‘ انہوں نے کہا: ’’میرے رب! مجھے دوبارہ زندہ فرما، تاکہ میں تیری راہ میں دوبارہ شہید کیا جاؤں۔‘‘ تو اللہ عزوجل نے فرمایا: ’’میری طرف سے یہ فیصلہ پہلے ہو چکا ہے کہ لوگ دنیا میں دوبارہ نہ بھیجے جائیں گے۔“ تو انہوں نے کہا: ’’یا رب! زندہ لوگوں کو ہماری طرف سے پیغام پہنچا دیجیے۔‘‘ تو اللہ تعالیٰ نے اس پر آیت:\n﴿ وَلَا تَحۡسَبَنَّ ٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتَۢاۚ بَلۡ أَحۡيَآءٌ عِندَ رَبِّهِمۡ يُرۡزَقُونَ ﴾ [آل عمران: ۱۶۹]\n’’جو لوگ اللہ کی راہ میں شہید ہوگئے انہیں ہرگز مردہ نہ سمجھو۔ وہ تو زندہ ہیں جو اپنے پروردگار کے ہاں سے رزق پا رہے ہیں۔‘‘\nنازل فرما دی۔‘‘","",{"k":"سنن الترمذي (3010)۔ سنن ابن ماجہ (190، 2800)۔ سنن سعید بن منصور (2550)"}],[104,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’جابر بن عبد اللہ رضی اللہ عنہ کے والد کا نام عبد اللہ بن عمرو بن حرام رضی اللہ عنہ تھا۔ وہ غزوہ احد میں شہید ہوئے تھے۔‘‘"],[105,"سیدنا جبیر بن مُطعِم رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’بلاشبہ اللہ تعالیٰ آسمانوں سے اوپر اپنے عرش پر ہے اور اس کے آسمان اس کی زمین پر گنبد کی طرح ہیں۔‘‘","",{"k":"التاریخ الکبیر للبخاري (2/224)۔ سنن أبي داؤد (4726)۔ التوحید لابن خزیمۃ (147)"}],[106,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ آیت کریمہ:\n﴿ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ ﴾ [السجدۃ: ۴]\n’’پھر وہ عرش پر مستوی ہوا۔‘‘\nکی تفسیر میں فرماتے ہیں: ’’عرش پانی پر ہے اور اللہ تعالیٰ عرش سے اوپر ہے جبکہ وہ ان تمام حالات کو جانتا ہے جو تم پر گزرتے ہیں۔‘‘","",{"k":"الرد علی الجہمیۃ للدارمي (81)۔ التوحید لابن خزیمۃ (594)۔ الأسماء والصفات للبیھقي (2/290)"}],[107,"قتادہ رحمہ اللہ فرمان باری تعالیٰ:\n﴿ وَهُوَ ٱلَّذِي فِي ٱلسَّمَآءِ إِلَٰهٌ وَفِي ٱلۡأَرۡضِ إِلَٰهٌۚ ﴾ [الزخرف: ۸۴]\n’’اور وہی ہے جو آسمانوں میں معبود ہے اور زمین میں بھی معبود ہے۔‘‘\nکی تفسیر میں فرماتے ہیں: ’’آسمانوں پر بھی اسی کی عبادت ہوتی ہے اور زمین پر بھی اسی کو پوجا جاتا ہے۔‘‘","",{"k":"ابن جریر (25/104)۔ الأسماء والصفات للبیھقي (2/343)"}],[108,"سیدنا عبد اللہ بن عباس رضی اللہ عنہ ارشاد الٰہی:\n﴿ يُدَبِّرُ ٱلۡأَمۡرَ مِنَ ٱلسَّمَآءِ إِلَى ٱلۡأَرۡضِ ثُمَّ يَعۡرُجُ إِلَيۡهِ فِي يَوۡمٍ كَانَ مِقۡدَارُهُۥٓ أَلۡفَ سَنَةٍ مِّمَّا تَعُدُّونَ ﴾ [السجدۃ: ۵]\n’’وہ آسمان سے زمین تک (ہر) معاملے کی تدبیر کرتا ہے، پھر وہ (معاملہ) اس کی طرف ایسے دن میں اوپر جاتا ہے جس کی مقدار ہزار سال ہے، اس (حساب) سے جو تم شمار کرتے ہو۔‘‘\nکی تفسیر میں فرماتے ہیں: ’’وہ دن چھ دنوں میں سے ایک دن ہے۔‘‘","",{"k":"المستدرك للحاکم (2/412)۔ تفسیر ابن جریر (21/91)"}],[109,"فرمان باری تعالیٰ ہے:\n﴿ ءَأَمِنتُم مَّن فِي ٱلسَّمَآءِ أَن يَخۡسِفَ بِكُمُ ٱلۡأَرۡضَ فَإِذَا هِيَ تَمُورُ ١٦ أَمۡ أَمِنتُم مَّن فِي ٱلسَّمَآءِ أَن يُرۡسِلَ عَلَيۡكُمۡ حَاصِبًاۖ ﴾ [الملک: ۱۶ - ۱۷]\n’’ کیا تم اس سے نڈر ہوگئے جو آسمان میں ہے کہ وہ تمہیں زمین میں دھنسادے۔ پھر وہ یکایک لرزنے لگے۔ یا تم اس سے بےخوف ہو گئے ہو جو آسمان میں ہے کہ وہ تم پر پتھراؤ والی آندھی بھیج دے۔‘‘"],[110,"سیدنا عمران بن حُصَین رضی اللہ عنہ بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے میرے والد سے پوچھا: ”اے حصین! آج کل تم کتنے معبودوں کو پوجتے ہو؟“میرے باپ نے جواب دیا: ’’سات کو۔ چھ زمین میں(رہتے ہیں) اور ایک آسمان میں۔‘‘ آپ صلی اللہ علیہ وسلم نے پوچھا: ”ان میں سے کس کی سب سے زیادہ رغبت، دلچسپی، امید اور خوف و ڈر کے ساتھ عبادت کرتے ہو؟“ انہوں نے کہا: ’’اس کی جو آسمان میں ہے۔‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اے حصین! سنو، اگر تم اسلام لے آتے تو میں تمہیں دو کلمے سکھا دیتا جو تمہیں برابر نفع پہنچاتے رہتے۔“ پھر جب حصین اسلام لے آئے تو انہوں نے عرض کیا: ’’اللہ کے رسول! مجھے وہ دونوں کلمے سکھا دیجیے جنہیں سکھانے کا آپ نے مجھ سے وعدہ فرمایا تھا۔‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ”کہو: «اَللّٰهُمَّ أَلْهِمْنِي رُشْدِي وَأَعِذْنِيْ مِنْ شَرِّ نَفْسِيْ»\n’’اے اللہ! تو مجھے میری بھلائی کی باتیں سکھا دے، اور میرے نفس کے شر سے مجھے بچا لے۔“","",{"k":"سنن الترمذي (3483)۔ الرد علی بشر المریسي للدارمي (1/227)۔ الآحاد والمثاني لابن أبي عاصم (4/323)"}],[111,"کسی عالم کا قول ہے:’’جہمیہ بذاتِ خود مُشَبِّہَہ ہیں کیونکہ وہ اپنے معبود کوگونگے اور بہرے بتوں سے تشبیہ دیتے ہیں جو نہ سنتے ہیں، نہ دیکھتے ہیں، نہ بات کرسکتے ہیں اور نہ ہی کسی چیز کو بنا سکتے ہیں۔ جہمیہ کے مطابق اللہ تعالیٰ بھی نہ بات کرتا ہے اور نہ اپنے آپ کو دیکھ سکتا ہے۔ ان کا کہنا ہے کہ اللہ کا اسم مخلوق ہے۔"],[112,"جہمیہ کے اس قول کی وجہ سے ان پر یہ لازم آتا ہے کہ اس بات کے بھی قائل ہوں کہ مؤذن اذان دیتے ہوئے کہے: ’’اس ذات کے علاوہ کوئی معبود نہیں جس کا نام اللہ ہے۔اور میں گواہی دیتا ہوں کہ محمد صلی اللہ علیہ وسلم اس ذات کے رسول ہیں جس کا نام اللہ ہے۔‘‘ کیونکہ وہ اس بات کے قائل ہیں کہ اللہ کا نام مخلوق ہے۔"],[113,"ایک مرتبہ ایک یہودی اور ایک مسلمان جہمیہ میں سے صفاتِ الٰہی کی نفی کرنے والے کے پاس اپنا مقدمہ لے کر گئے تو اس نے فیصلہ کیا کہ مسلمان قسم کھائے۔ یہودی نے مسلمان سے کہا: ’’قسم کھاؤ۔ ‘‘ قاضی نے مسلمان سے کہا کہ یوں قسم کھاؤ: ’’میں اس اللہ کی قسم کھاتا ہوں کہ جس کے علاوہ کوئی معبود حقیقی نہیں ہے۔‘‘ تو یہودی کہنے لگا: ’’اس سے کہو کہ خالق کی قسم کھاؤ، مخلوق کی نہیں۔کیونکہ جو الفاظ تم نے کہے ہیں، وہ تو قرآن کا حصہ ہیں، اور تمہارے نزدیک قرآن مخلوق ہے۔ لہٰذا اسے کہو کہ خالق کی قسم کھائے۔‘‘ یہ سن کر وہ جہمی قاضی حیران پریشان ہوگیا اور کہنے لگا: ’’تم دونوں ابھی جاؤ، میں تمہارے معاملے میں مزید غور وفکر کروں گا۔‘‘ یوں باطل پرستوں نے اس موقع پر خسارہ پایا۔","",{"k":"شرح أصول اعتقاد أھل السنۃ لللالکائي (2/211)۔ الأسماء والصفات للبیھقي (1/619)۔ الرد علی الجھمیۃ للإمام أحمد (ص 143)"}],[114,"معاویہ بن عمار کہتے ہیں کہ میں نے جعفر بن محمد رحمہ اللہ سے قرآن کے متعلق پوچھا تو انہوں نے فرمایا: ’’قرآن نہ خالق ہے، نہ مخلوق۔‘‘","",{"k":"پوائنٹ نمبر 17 میں اس کی تخریج گزر چکی ہے۔"}],[115,"ابو عبید فرماتے ہیں: ’’جہمیہ اپنی باتوں کےلیے بطور دلیل چند آیات پیش کرتے ہیں۔ ان میں سے تین آیات سے ان کا استدلال بہت زیادہ دھوکے میں ڈالنے والا ہے۔ پہلی آیت ہے:\n﴿ وَخَلَقَ كُلَّ شَيۡءٍ فَقَدَّرَهُۥ تَقۡدِيرًا ﴾ [الفرقان: ۲]\n’’اور اللہ تعالیٰ نے ہر چیز کو پیدا کرکے ایک مناسب اندازہ ٹھہرا دیا ہے۔‘‘\nوہ کہتے ہیں: ’’اگر تم کہتے ہو کہ قرآن کوئی چیز نہیں ہے تو تم نے کفر کا ارتکاب کرلیا۔ اور اگر تم یہ کہتے ہو کہ قرآن کوئی چیز ہے تو پھر وہ اس آیت کے مفہوم میں شامل ہے۔\nدوسری آیت ہے:\n﴿ إِنَّمَا ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلۡقَىٰهَآ إِلَىٰ مَرۡيَمَ وَرُوحٌ مِّنۡهُۖ ﴾ [النساء: ۱۷۱]\n’’مسیح عیسیٰ بن مریم علیہ السلام تو صرف اللہ تعالیٰ کے رسول اور اس کا کلمہ ہیں، جسے اس نے مریم علیہا السلام کی طرف ڈال دیا تھا اور اس کے پاس کی روح ہیں۔‘‘\nان کا کہنا ہے: ’’تم تو عیسائیوں والی باتیں کرتے ہو کیونکہ مسیح علیہ السلام اللہ کا کلمہ ہیں اور مخلوق ہیں اور تم کہتے ہو کہ کلام اللہ مخلوق نہیں ہے، حالانکہ عیسیٰ بھی تو کلام اللہ میں سے ہی ہیں۔‘‘\nتیسری آیت ہے:\n﴿ مَا يَأۡتِيهِم مِّن ذِكۡرٍ مِّن رَّبِّهِم مُّحۡدَثٍ ﴾ [الأنبیاء: ۲]\n’’ان کے پاس ان کے رب کی طرف سے جو بھی نئی نئی نصیحت آتی ہے۔‘‘\nجہمیہ بطور اعتراض کہتے ہیں کہ تم کہتے ہو کہ قرآن نئی پیدا شدہ چیز نہیں ہے۔‘‘"],[116,"امام ابو عبید رحمہ اللہ ان کے اعتراضات کا جواب دیتے ہوئے فرماتے ہیں: ’’جہاں تک اللہ تعالیٰ کے فرمان: ﴿ وَخَلَقَ كُلَّ شَيۡءٍۖ ﴾ کا تعلق ہے تو بات وہی ہے جو اللہ نے فرما دی ہے، (جیسا کہ) دوسری آیت میں ہے:\n﴿ إِنَّمَا قَوۡلُنَا لِشَيۡءٍ إِذَآ أَرَدۡنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ ﴾ [النحل: ۴۰]\n’’ہم جب کسی چیز کا اراده کرتے ہیں تو صرف ہمارا یہ کہہ دینا ہوتا ہے کہ ہوجا، پس وه ہوجاتی ہے۔‘‘\nاس آیت میں اللہ تعالیٰ نے واضح فرما دیا ہے کہ اس نے پہلی مخلوق اپنے فرمان کے ذریعہ پیدا کی ہے اور پہلی مخلوق کا تعلق اس چیز سے ہے جس کے بارے میں فرمایا ہے: ﴿ وَخَلَقَ كُلَّ شَيۡءٍۖ ﴾ تو اس طرح اللہ تعالیٰ نے بتایا ہے کہ اس کا کلام مخلوق سے پہلے ہے۔"],[117,"جہاں تک ان کے آیت: ﴿ إِنَّمَا ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ ﴾ میں تحریف کا تعلق ہے تو اگر بات وہی ہوتی جو ان کا نظریہ ہے تو مناسب یہ تھا کہ قرآن میں الفاظ یوں ہوتے: «وکلمتہ ألقاہ إلی مریم» کیونکہ عیسیٰ علیہ السلام مذکر ہیں اور لفظ ’’کلمہ‘‘ مؤنث ہے۔ اس میں کسی عربی بولنے والے کا اختلاف نہیں ہے۔ اصل بات یہ ہے کہ اللہ تعالیٰ نے عیسیٰ علیہ السلام کو کلمہ کے ذریعہ پیدا فرمایا ہے، نہ کہ عیسیٰ علیہ السلام کلمہ ہیں۔ کیا آپ نے یہ فرمان باری تعالیٰ نہیں سنا؟ ﴿ وَكَلِمَتُهُۥٓ أَلۡقَىٰهَآ إِلَىٰ مَرۡيَمَ وَرُوحٌ مِّنۡهُۖ ﴾ روح سے مراد جبریل علیہ السلام ہیں جیسا کہ دوسری آیت میں وضاحت ہے:\n﴿ فَأَرۡسَلۡنَآ إِلَيۡهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرًا سَوِيًّا ﴾ [مریم: ۱۷]\n’’پھر ہم نے اس کے پاس اپنی روح (جبرائیل علیہ السلام) کو بھیجا، پس وه اس کے سامنے پورا آدمی بن کر ظاہر ہوا۔‘‘\nدوسرے مقام پر فرمایا:\n﴿ إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَۖ خَلَقَهُۥ مِن تُرَابٍ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ ﴾ [آل عمران: ۵۹]\n’’اللہ تعالیٰ کے نزدیک عیسیٰ علیہ السلام کی مثال ہو بہو آدم علیہ السلام کی مثال ہے جسے مٹی سے بنا کر کے کہہ دیا کہ ہو جا! پس وه ہو گیا!۔‘‘\nتو اللہ تعالیٰ نے عیسیٰ اور آدم علیہما السلام کو اپنے کلمہ کُنْ کے ذریعہ پیدا فرمایا ہے۔ لہٰذا ان دونوں آیات میں کوئی اختلاف نہیں ہے۔"],[118,"جہاں تک ان کے آیت: ﴿ مِّن ذِكۡرٍ مِّن رَّبِّهِم مُّحۡدَثٍ ﴾ میں تحریف کا معاملہ ہے تو بات یہ ہے قرآن نبی کریم صلی اللہ علیہ وسلم اور صحابہ کرام رضی اللہ عنہم کے پاس تازہ تازہ آتا تھا کیونکہ اللہ تعالیٰ نے آپ صلی اللہ علیہ وسلم کو وہ چیز سکھائی تھی جو آپ صلی اللہ علیہ وسلم نہیں جانتے تھے۔"],[119,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’قرآن کلام اللہ ہے، مخلوق نہیں ہے کیونکہ فرمان الٰہی ہے: ﴿ إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يُغۡشِي ٱلَّيۡلَ ٱلنَّهَارَ يَطۡلُبُهُۥ حَثِيثًا وَٱلشَّمۡسَ وَٱلۡقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتِۭ بِأَمۡرِهِۦٓۗ ﴾ ’’بے شک تمہارا رب اللہ ہی ہے جس نے سب آسمانوں اور زمین کو چھ روز میں پیدا کیا ہے، پھر عرش پر قائم ہوا۔ وه شب سے دن کو ایسے طور پر چھپا دیتا ہے کہ وه شب اس دن کو جلدی سے آ لیتی ہے اور سورج اور چاند اور دوسرے ستاروں کو پیدا کیا ایسے طور پر کہ سب اس کے حکم کے تابع ہیں۔‘‘ اس آیت میں اللہ تعالیٰ نے واضح کیا ہے کہ تمام مخلوقات کا ہونا، جلدی چلنا اور تابع ہونا اللہ کے حکم سے ہے۔ پھر اللہ تعالیٰ نے اس کی تفصیل بیان کرتے ہوئے فرمایا:\n﴿ أَلَا لَهُ ٱلۡخَلۡقُ وَٱلۡأَمۡرُۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ ﴾ [الأعراف: ۵۴]\n’’یاد رکھو اللہ ہی کے لئے خاص ہے خالق ہونا اور حاکم ہونا، بڑی خوبیوں سے بھرا ہوا ہے اللہ جو تمام عالم کا پروردگار ہے۔‘‘"],[120,"سفیان بن عیینہ رحمہ اللہ فرماتے ہیں: ’’اللہ تعالیٰ نے اپنے فرمان: ﴿ أَلَا لَهُ ٱلۡخَلۡقُ وَٱلۡأَمۡرُۗ ﴾ کے ذریعہ یہ بات واضح فرما دی ہے کہ مخلوق اللہ کے حکم سے ہے۔ جیسا کہ دوسری جگہ فرمایا:\n﴿ لِلَّهِ ٱلۡأَمۡرُ مِن قَبۡلُ وَمِنۢ بَعۡدُۚ ﴾ [الروم: ۴]\n’’اس سے پہلے اور اس کے بعد بھی حکم اللہ تعالیٰ ہی کا ہے۔‘‘\nایک اور جگہ فرمایا:\n﴿ إِنَّمَآ أَمۡرُهُۥٓ إِذَآ أَرَادَ شَيۡـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ ﴾ [یس: ۸۲]\n’’اس کی شان یہ ہے کہ جب وہ کسی چیز کا ارادہ کرتا ہے تو اس سے فرما دیتا ہے کہ ہوجا تو وہ ہوجاتی ہے۔‘‘\nایک اور جگہ فرمایا:\n﴿ وَمِنۡ ءَايَٰتِهِۦٓ أَن تَقُومَ ٱلسَّمَآءُ وَٱلۡأَرۡضُ بِأَمۡرِهِۦۚ ﴾ [الروم: ۲۵]\n’’اس کی ایک نشانی یہ بھی ہے کہ آسمان وزمین اسی کے حکم سے قائم ہیں۔‘‘\nاس آیت میں یہ نہیں فرمایا کہ ’’اسی کی تخلیق سے۔‘‘","",{"k":"السنۃ للخلال (5/109)۔ الشریعۃ للآجري (1/504 – 505)۔ الأسماء والصفات للبیھقي (1/556، 610)"}],[121,"مجاہد بن جبر رحمہ اللہ (المتوفیٰ: 101ھ تقریباً) کہتے ہیں کہ میں نے سیدنا عبد اللہ بن عباس رضی اللہ عنہما سے پوچھا: ’’تقدیر کیا ہے؟‘‘ انہوں نے فرمایا: ’’اے مجاہد! اللہ تعالیٰ کا فرمان یاد نہیں: ﴿ أَلَا لَهُ ٱلۡخَلۡقُ وَٱلۡأَمۡرُۗ ﴾ [الأعراف: ۵۴]","",{"k":"سند ضعیف ہے۔ ابن جریج مدلس ہیں، سماع کی تصریح نہیں۔ جبکہ یحییٰ بن ایوب کے حافظہ پر علماء نے کلام کیا ہے۔"}],[122,"سعید بن جبیر رحمہ اللہ (المتوفیٰ: 95ھ) روایت کرتے ہیں کہ سیدنا عبد اللہ بن عباس رضی اللہ عنہ نے فرمایا: ’’مسلمانوں کو رومیوں کا فارسیوں پر فتح پانا محبوب تھا کیونکہ رومی اہل کتاب تھے، جبکہ مشرکین کو فارسیوں کا رومیوں پر غالب آنا پسند تھا کیونکہ فارسی بت پرست تھے۔ مسلمانوں نے اس بات کا تذکرہ ابو بکر رضی اللہ عنہ سے کیا اور ابو بکر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے کہا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’وہ ضرور شکست کھائیں گے۔‘‘ ابو بکر رضی اللہ عنہ نے مشرکین کے پاس جا کر انہیں یہ بات بتائی۔ انہوں نے کہا: ’’(ایسی بات ہے تو) ہمارے اور اپنے درمیان کوئی مدت متعین کر لو۔ اگر تم غالب آ گئے (جیت گئے) تو ہم تمہیں اتنا اتنا دیں گے، اور اگر ہم غالب آ گئے تو ہمیں تم اتنا اتنا دینا۔‘‘ تو انہوں نے پانچ سال کی مدت رکھ دی۔ لیکن وہ (رومی) اس مدت میں غالب نہ آ سکے۔ ابوبکر رضی اللہ عنہ نے یہ بات بھی رسول اللہ صلی اللہ علیہ وسلم کو بتائی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”تم نے اس کی مدت اس سے کچھ آگے کیوں نہ بڑھا دی؟ “ راوی کہتے ہیں: ’’میرا خیال ہے کہ آپ کی مراد اس سے دس (سال) تھی۔‘‘ سعید بن جبیر رحمہ اللہ کہتے ہیں کہ «بضع» دس سے کم کو کہتے ہیں۔ اس کے بعد رومی غالب آ گئے۔ (ابن عباس رضی اللہ عنہ) کہتے ہیں: اللہ تعالیٰ کے فرمان: ﴿ الٓمٓ ١ غُلِبَتِ ٱلرُّومُ ٢ فِيٓ أَدۡنَى ٱلۡأَرۡضِ وَهُم مِّنۢ بَعۡدِ غَلَبِهِمۡ سَيَغۡلِبُونَ ٣ فِي بِضۡعِ سِنِينَۗ لِلَّهِ ٱلۡأَمۡرُ مِن قَبۡلُ وَمِنۢ بَعۡدُۚ ﴾ ’’الم، رومی مغلوب ہوگئے، قریب کی سرزمین میں اور وہ اپنی اس مغلوبیت کے بعد عنقریب غالب آجائیں گے، چند سالوں میں۔ معاملہ اس سے پہلے بھی اللہ کے ہاتھ میں ہے اور اس کے بعد بھی۔‘‘ کا یہی مفہوم ہے۔ فرماتے ہیں: ’’رومی پہلے مغلوب ہوئے اور اس کے بعد غالب آئے۔ اللہ تعالیٰ نے فرمایا تھا: ﴿ وَيَوۡمَئِذٍ يَفۡرَحُ ٱلۡمُؤۡمِنُونَ ﴾ ’’اور اس دن مسلمان خوش ہوں گے۔‘‘تو اللہ کی مدد پر مسلمان بہت خوش ہوئے۔","",{"k":"سنن الترمذي: 5/343، حدیث: 3193، السنن الکبری للنسائي: 6/426، حدیث: 11389، مسند الإمام أحمد: 1/276، 304۔ اس کا ایک شاہد ہے جس کی تخریج پوائنٹ نمبر 94 میں گزر چکی ہے۔"}],[123,"ابن المثنی از ابو سعید تغلبی از ابو اسحاق الفزاری از سفیان کی سند سے بھی یہی روایت مروی ہے۔"],[124,"امام بخاری رحمہ اللہ فرماتے ہیں جہاں تک بندوں کے افعال کی بات ہے تو سیدنا حذیفہ بن یمان رضی اللہ عنہ (المتوفیٰ: 36ھ) بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بلاشبہ اللہ تعالیٰ ہر کاریگر اور اس کی کاریگری کو بناتا ہے۔‘‘ اسی موقع پر بعض علماء نے یہ آیت تلاوت کی ہے:\n﴿ وَٱللَّهُ خَلَقَكُمۡ وَمَا تَعۡمَلُونَ ﴾ [الصافات: ۹۶]\n’’حالانکہ اللہ ہی نے تمہیں پیدا کیا اور اسے بھی جو تم کرتے ہو۔‘‘\nتو اس آیت کے ذریعہ اللہ تعالیٰ نے بتایا ہے کہ مختلف چیزیں اور انہیں بنانے والے مخلوق ہیں۔","",{"k":"السنۃ لابن أبي عاصم (357 – 358)۔ مسند البزار (2837)۔ المستدرك علی الصحیحین للحاکم (1/310)"}],[125,"سیدنا حذیفہ رضی اللہ عنہ فرماتے ہیں: ’’بلا شبہ اللہ تعالیٰ نے ہر کاریگر اور اس کی کاریگری کو بنایا ہے۔ اللہ تعالیٰ ہر ٹوکری بنانے والے اور اس کی کاریگری کا خالق ہے۔‘‘"],[126,"حذیفہ رضی اللہ عنہ سے مروی یہ روایت اعمش سے وکیع نے بھی بیان کی ہے۔"],[127,"طاؤس رحمہ اللہ (المتوفیٰ: 106ھ) بیان کرتے ہیں کہ سیدنا عبد اللہ بن عباس رضی اللہ عنہما نے فرمایا: ’’بےبسی اور عقلمندی کا تعلق تقدیر سے ہے۔‘‘","",{"k":"مصنف عبد الرزاق (11/118)"}],[128,"طاؤس یمانی رحمہ اللہ فرماتے ہیں: ’’میں نے رسول اللہ صلی اللہ علیہ وسلم کے صحابہ میں سے جن لوگوں سے ملاقات کی ہے، وہ سب اس بات کے قائل تھے کہ ہر چیز تقدیر میں لکھی ہوئی ہے۔ میں نے عبد اللہ بن عمر رضی اللہ عنہما سے سنا، وہ بیان کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہر چیز تقدیر میں لکھی ہوئی ہے، حتیٰ کہ بےبسی اور عقلمندی بھی۔‘‘","",{"k":"مؤطا مالك (2/899)۔ صحیح مسلم (2655)"}],[129,"طاؤس رحمہ اللہ بیان کرتے ہیں کہ سیدنا عبد اللہ بن عباس رضی اللہ عنہما نے آیت:\n﴿ إِنَّا كُلَّ شَيۡءٍ خَلَقۡنَٰهُ بِقَدَرٍ ﴾ [القمر: ۴۹]\n’’بلاشبہ ہم نے ہر چیز کو ایک مقدار سے پیدا کیا ہے۔‘‘\nکی تفسیر میں فرمایا: ’’یہاں تک کہ بےبسی اور عقلمندی بھی۔‘‘","",{"k":"القدر للفریابي، ص: 190، رقم: 304، الشریعۃ للآجري: 2/869، رقم: 447۔ پوائنٹ نمبر 127 کو بھی دیکھ لیجیے۔"}],[130,"طاؤس رحمہ اللہ بیان کرتے ہیں کہ سیدنا عبد اللہ بن عمر رضی اللہ عنہما نے فرمایا: ’’ہر چیز تقدیر میں ہے یہاں تک کہ بےبسی اور عقلمندی بھی۔‘‘","",{"k":"القدر للفریابي، ص: 190، نمبر: 302۔ پوائنٹ نمبر 128 سے واضح ہے کہ یہ رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے۔"}],[131,"سیدنا عبد اللہ بن عباس رضی اللہ عنہما فرماتے ہیں: ’’ہر چیز تقدیر میں ہے حتیٰ کہ تمہارا اپنے گال پر ہاتھ رکھنا بھی تقدیر میں لکھا ہوا ہے۔‘‘","",{"k":"التاریخ الکبیر للبخاري (1/318)۔ القدر للفریابي (ص 143)۔ نمبر (206)"}],[132,"یحییٰ بن سعید القطان رحمہ اللہ فرماتے ہیں کہ میں نے محدثین کو ہمیشہ یہی کہتے سنا ہے کہ بندوں کے افعال مخلوق ہیں۔‘‘","",{"k":"الأسماء والصفات للبیھقي (2/6 – 7)"}],[133,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’بندوں کی حرکت، آواز، عمل اور لکھائی مخلوق ہے جبکہ تلاوت اور بیان ہونے والا قرآن، جو مصاحف میں لکھا ہوا ہے اور دلوں میں محفوظ ہے، وہ کلام اللہ ہے، مخلوق نہیں ہے۔ فرمان الٰہی ہے:\n﴿ بَلۡ هُوَ ءَايَٰتُۢ بَيِّنَٰتٌ فِي صُدُورِ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَۚ ﴾ [العنکبوت: ۴۹]\n’’ بلکہ یہ (قرآن) تو واضح آیات ہیں جو ان لوگوں کے سینوں میں محفوظ ہیں جنہیں علم دیا گیا ہے۔‘‘"],[134,"امام اسحاق بن ابراہیم ابن راہویہ رحمہ اللہ (المتوفیٰ: 238ھ) فرماتے ہیں: ’’جہاں تک محفوظ کرنے والے (بندوں، دلوں، مصاحف یا کانوں) کا تعلق ہے تو ان کے مخلوق ہونے میں کسے شک ہوسکتا ہے؟‘‘"],[135,"فرمان باری تعالیٰ ہے:\n﴿ وَكِتَٰبٍ مَّسۡطُورٍ ٢ فِي رَقٍّ مَّنشُورٍ ﴾ [الطور: ۲ - ۳]\n’’ اور اس کتاب کی قسم جو کھلے ہوئے صفحات میں لکھی ہوئی ہے۔‘‘\nایک اور مقام پر فرمایا:\n﴿ بَلۡ هُوَ قُرۡءَانٌ مَّجِيدٌ ٢١ فِي لَوۡحٍ مَّحۡفُوظِۭ ﴾ [البروج: ۲۱ - ۲۲]\n’’ بلکہ یہ قرآن بڑی شان والا ہے جو لوح محفوظ میں (درج ہے۔)‘‘\nان آیات میں اللہ تعالیٰ نے اس بات کا تذکرہ کیا ہے کہ قرآن کو محفوظ بھی کیا جاتا ہے اور لکھا بھی جاتا ہے۔ ایک اور جگہ پر فرمایا:\n﴿ وَمَا يَسۡطُرُونَ ﴾ [القلم: ۱]\n’’اور اس کی قسم جو (کاتبان وحی یا فرشتے) لکھتے ہیں۔‘‘"],[136,"قتادہ رحمہ اللہ فرماتے ہیں: آیت: ﴿ وَٱلطُّورِ ١ وَكِتَٰبٍ مَّسۡطُورٍ ﴾ میں مسطور سے مراد لکھی ہوئی ہے۔جبکہ ﴿ فِي رَقٍّ مَّنشُورٍ ﴾ سے مراد کتاب ہے۔","",{"k":"ابن جریر (27/16)۔ تفسیر عبد الرزاق (3/246)"}],[137,"مجاہد رحمہ اللہ فرماتے ہیں: ﴿ وَكِتَٰبٍ مَّسۡطُورٍ ﴾ سے مراد لکھے ہوئے صحیفے ہیں۔ جبکہ ﴿ فِي رَقٍّ مَّنشُورٍ ﴾ سے مراد صحیفے ہیں۔","",{"k":"ابن جریر (27/15 – 16)۔ الأسماء والصفات للبیھقي (2/7)"}],[138,"سیدہ ام سلمہ رضی اللہ عنہا (المتوفیٰ: 62 ھ) بیان کرتی ہیں کہ میں نے (حجۃ الوداع کے موقع پر) طواف کیا تو رسول اللہ صلی اللہ علیہ وسلم بیت اللہ کے پہلو میں کھڑے نماز میں سورت طور کی تلاوت کررہے تھے۔","",{"k":"مؤطا مالك (1/371)۔ صحیح البخاري (464)"}],[139,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’نبی کریم صلی اللہ علیہ وسلم نے اللہ کی حمد وثناء کرنے والے بندوں کی بات، دعاء، نماز اور اللہ عز وجل کے سامنے عاجزی وانکساری کو واضح کیا ہے اور جو کچھ زندہ اور سب کو قائم رکھنے والا (یعنی اللہ) انہیں جواب دیتا ہے، اس کی وضاحت فرمائی ہے۔ آپ صلی اللہ علیہ وسلم نے (مختلف احادیث میں) فرمایا ہے: «اقْرَؤُوا إِنْ شِئْتُمْ» ’’اگر تم چاہو تو فلاں آیت پڑھ لو۔‘‘ (مثلاً) بندہ کہتا ہے:\n﴿ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴾ [الفاتحۃ: ۲]\n’’تمام تعریفیں اس اللہ کےلیے ہیں جو تمام جہانوں کو پالنے والا ہے۔‘‘\nتو اللہ تعالیٰ فرماتے ہیں: ’’میرے بندے نے میری تعریف کی۔‘‘","",{"k":"صحیح البخاري (2399، 4781)۔ سنن الترمذي (3292)"}],[140,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے نماز میں سورۂ فاتحہ نہیں پڑھی تو اس کی نماز پوری نہیں ہوئی بلکہ اس کی نماز ناقص رہی۔“ ابو سائب مولیٰ ہشام بن زہرہ کہتے ہیں کہ میں نے کہا: ’’ابوہریرہ! بسا اوقات میں امام کے پیچھے ہوتا ہوں (تو کیا کروں؟)‘‘ سیدنا ابوہریرہ رضی اللہ عنہ نے جواباً کہا: ’’اے فارسی! اس وقت تم دل میں سورۂ فاتحہ پڑھ لیا کرو کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو اللہ عزوجل کا یہ فرمان بیان کرتے ہوئے سنا ہے: ”نماز میرے اور میرے بندے کے درمیان آدھی آدھی تقسیم ہو چکی ہے۔ اور میرا بندہ جو سوال کرتا ہے وہ پورا کیا جاتا ہے۔ جب کوئی شخص ﴿ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴾ کہتا ہے تو اللہ عزوجل فرماتا ہے: ’’میرے بندے نے میری تعریف کی۔‘‘ نمازی جب ﴿ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ ﴾ کہتا ہے تو اللہ تعالیٰ فرماتا ہے کہ میرے بندہ نے میری توصیف کی۔ نمازی جب ﴿ مَٰلِكِ يَوۡمِ ٱلدِّينِ ﴾ کہتا ہے تو اللہ عزوجل فرماتا ہے: ’’میرے بندے نے میری بزرگی بیان کی۔‘‘ اور یوں بھی کہتا ہے کہ میرے بندے نے اپنے سب کام میرے سپرد کر دیے ہیں۔ نمازی جب ﴿ إِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ ﴾ پڑھتا ہے۔ تو اللہ عزوجل فرماتا ہے: ’’یہ میرے اور میرے بندے کا درمیانی معاملہ ہے۔‘‘ پھر جب نمازی اپنی نماز میں ﴿ ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ ٦ صِرَٰطَ ٱلَّذِينَ أَنۡعَمۡتَ عَلَيۡهِمۡ غَيۡرِ ٱلۡمَغۡضُوبِ عَلَيۡهِمۡ وَلَا ٱلضَّآلِّينَ ﴾ پڑھتا ہے تو اللہ تعالیٰ جواب دیتا ہے کہ یہ سب میرے اِس بندے کےلیے ہے اور یہ جو کچھ طلب کرے گا، اسے دیا جائے گا۔“","",{"k":"مؤطا مالك (1/84)۔ صحیح مسلم (395)"}],[141,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’جہاں تک قلم، دوات اور اوراق کی بات ہے تو یہ سب چیزیں مخلوق ہیں، مثلاً آپ لکھتے ہیں: ’’اللہ۔‘‘ تو اللہ تعالیٰ تو اپنی ذات میں خالق ہی ہے جبکہ آپ کا فعل ’’لکھنا‘‘ اور ’’محنت کرنا‘‘ مخلوق ہے، کیونکہ اللہ تعالیٰ (کی ذات) کے علاوہ اللہ جو بھی بناتا ہے، وہ مخلوق ہے۔فرمان الٰہی ہے:\n﴿ وَخَلَقَ كُلَّ شَيۡءٍ فَقَدَّرَهُۥ تَقۡدِيرًا ﴾ [الفرقان: ۲]\n’’اس نے ہر چیز کو پیدا کیا تو اس کا ٹھیک ٹھیک اندازہ کیا۔‘‘\nدوسری جگہ فرمایا:\n﴿ وَإِنَّهُۥ فِيٓ أُمِّ ٱلۡكِتَٰبِ لَدَيۡنَا لَعَلِيٌّ حَكِيمٌ ﴾ [الزخرف: ۴]\n’’بلاشبہ یہ قرآن ام الکتاب (لوح محفوظ) میں درج ہے جو ہمارے پاس بڑی بلند مرتبہ اور حکمت والی کتاب ہے۔‘‘\nتیسرے مقام پر فرمایا:\n﴿ بَلۡ هُوَ قُرۡءَانٌ مَّجِيدٌ ٢١ فِي لَوۡحٍ مَّحۡفُوظِۭ ﴾ [البروج: ۲۱ - ۲۲]\n’’ بلکہ یہ قرآن بڑی شان والا ہے جو لوح محفوظ میں (درج ہے۔)‘‘"],[142,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ مشرکینِ قریش آپ صلی اللہ علیہ وسلم کے پاس آئے اور تقدیر کے بارے میں جھگڑنے لگے تو یہ آیت نازل ہوئی:\n﴿ إِنَّا كُلَّ شَيۡءٍ خَلَقۡنَٰهُ بِقَدَرٍ ﴾ [القمر: ۴۹]\n’’بے شک ہم نے ہرچیز کو ایک (مقررہ) اندازے سے پیدا کیا ہے۔‘‘"],[143,"یہ روایت ابو نعیم کے علاوہ قبیصہ نے بھی سفیان کی سند سے بیان کی ہے۔","",{"k":"صحیح مسلم (2656)"}],[144,"سیدنا عبد اللہ بن عمرو بن العاص رضی اللہ عنہ بیان کرتے ہیں کہ درج ذیل آیت:\n﴿ إِنَّ ٱلۡمُجۡرِمِينَ فِي ضَلَٰلٍ وَسُعُرٍ ﴾ [القمر: ۴۷]\n’’یقیناً مجرم لوگ بڑی گمراہی اور دیوانگی میں ہیں۔‘‘\nمنکرین ِ تقدیر کے بارے میں نازل ہوئی ہے۔","",{"k":"مسند البزار: 6/436۔ اس روایت کی سند میں یونس بن حارث کو ابن معین اور ابن حبان نے ثقہ قرار دیا ہے جبکہ اس میں کچھ ضعف ہے۔ تہذیب الکمال میں اس کے بارے میں ابن معین کا قول یوں ہے: ’’ضعیف ہے، (سند میں) اس کا وجود اور عدم وجود برابر ہے۔‘‘"}],[145,"اس بارے میں سیدنا عبد اللہ بن عباس اور سیدنا معاذ بن انس رضی اللہ عنہما سے بھی روایات منقول ہیں۔","",{"k":"عبد اللہ بن عباس رضی اللہ عنہ کا اثر الإبانۃ لابن بطۃ: 2/162۔ شرح أصول اعتقاد أھل السنۃ لللالکائي: 2/643، 747۔ السنن الکبری للبیھقي: 10/205۔ سیدنا معاذ بن انس رضی اللہ عنہ جلیل القدر صحابہ میں سے ہیں۔ ان کے اثر کا حوالہ نہیں مل سکا۔"}],[146,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ابوبکر صدیق رضی اللہ عنہ نے عرض کیا: ’’اللہ کے رسول! مجھے کچھ ایسے کلمات بتائیے جنہیں میں صبح اور شام کہہ لیا کروں، آپ نے فرمایا: کہو: «اللَّهُمَّ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، فَاطِرَ السَّموَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ.، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَشَرِّ الشَّيْطَانِ وَشِرْكِهِ».\n”اے اللہ! آسمانوں اور زمین کے پیدا کرنے والے، پوشیدہ اور موجود ہر چیز کے جاننے والے، ہر چیز کے پالنہار اور مالک! میں گواہی دیتا ہوں کہ تیرے سوا کوئی معبود برحق نہیں ہے، میں تیری ذات کے ذریعہ اپنے نفس کے شر سے، شیطان کے شر سے، اور اس کے شرک سے پناہ مانگتا ہوں“ آپ صلی اللہ علیہ وسلم نے فرمایا: ”صبح، شام اور جب سونے چلو، تب اس دعا کو پڑھ لیا کرو۔“","",{"k":"الأدب المفرد للبخاري (1202)۔ مسند أحمد (2/297)۔ سنن أبي داود (3392)"}],[147,"سعد بن ربیع نے شعبہ کی سند سے یہی روایت بیان کی ہے۔","",{"k":"الأدب المفرد للبخاري، ص: 412، حدیث: 1202۔ یہ روایت آگے نمبر 616 سے 620 میں بھی آئے گی۔"}],[148,"سیدنا ابو ہریرہ رضی اللہ عنہ نے سیدنا ابو بکر رضی اللہ عنہ کی یہی روایت نقل کی ہے اور اس میں یہ الفاظ ہیں: «رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ» ’’ہر چیز کے رب اور مالک۔‘‘","",{"k":"المستدرك للحاکم (1/513)"}],[149,"یہ روایت مسدد نے ہشیم کے واسطے سے بھی بیان کی ہے۔","",{"k":"الأدب المفرد (1203)۔ سنن أبي داود (5067)"}],[150,"سیدنا جابر بن عبداللہ رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اذان سن کر یہ کہے: «اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ»\n’’اے اللہ! اس کامل دعوت اور قائم ہونے والی نماز کے رب! محمد صلی اللہ علیہ وسلم کو وسیلہ اور فضیلت عطا فرما اور انہیں اس مقام محمود پر پہنچا دے جس کا تو نے ان سے وعدہ فرمایا ہے۔‘‘ تواسے قیامت کے دن میری شفاعت ملے گی۔","",{"k":"صحیح البخاري (614)"}],[151,"سیدنا انس بن مالک رضی اللہ عنہ اور دیگر اہل علم سے منقول ہے کہ انہوں نے آیت قرآنی:\n﴿ فَوَرَبِّكَ لَنَسۡـَٔلَنَّهُمۡ أَجۡمَعِينَ ٩٢ عَمَّا كَانُواْ يَعۡمَلُونَ ﴾ [الحجر: ۹۳]\n’’تو آپ کے رب کی قسم! ہم ضرور ان تمام سے اس بارے میں پوچھیں گے جو وہ کرتے تھے۔‘‘\nکی تفسیر میں فرمایا کہ اس سے مراد کلمہ طیبہ کے بارے میں پوچھا جانا ہے۔","",{"k":"تفسیر ابن جریر: 14/67۔ اس کی سند میں بشر بن دینار مجہول ہے اور لیث بن ابی سلیم ضعیف ہے۔ یہی تفسیر مرفوعاً بھی منقول ہے۔ دیکھیے: سنن الترمذي: 5/298، حدیث: 3126۔ حافظ ابن حجر لکھتے ہیں: ’’اس کی سند میں ضعف ہے۔‘‘ فتح الباري: 1/78"}],[152,"اللہ عزوجل کا فرمان ہے:\n﴿ وَتِلۡكَ ٱلۡجَنَّةُ ٱلَّتِيٓ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ ﴾ [الزخرف: ۷۲]\n’’اور یہ وہ جنت ہے جس کا تمہیں تمہارے اعمال کے بدلے وارث بنا دیا گیا ہے۔‘‘\nدوسری جگہ فرمایا:\n﴿ لِمِثۡلِ هَٰذَا فَلۡيَعۡمَلِ ٱلۡعَٰمِلُونَ ﴾ [الصافات: ۶۱]\n’’اس جیسی کامیابی کے لیے لازم ہے کہ عمل کرنے والے عمل کریں۔‘‘\nایک اور جگہ فرمایا:\n﴿ جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ ﴾ [السجدۃ: ۱۷]\n’’یہ ان کاموں کا بدلہ ہوگا جو وہ کیا کرتے تھے۔‘‘"],[153,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا: ’’کون سا عمل افضل ہے؟‘‘ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ پر ایمان لانا اور اس کے راستہ میں جہاد کرنا۔‘‘"],[154,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے دریافت کیا گیا کہ کون سا عمل سب سے افضل ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ اور اس کے رسول پر ایمان لانا۔“پوچھا گیا: ’’اس کے بعد کون سا؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا کہ ”اللہ کی راہ میں جہاد کرنا۔“ پوچھا گیا:’’پھر کیا ہے؟‘‘ فرمایا: ”حج مبرور۔“","",{"k":"صحیح البخاري (26)۔ صحیح مسلم (83)"}],[155,"عبد العزیز بن عبد اللہ از ابراہیم از ابن شہاب از سعید از ابو ہریرہ رضی اللہ عنہ کی سند سے بھی یہ متن مروی ہے۔","",{"k":"صحیح البخاري (1519)"}],[156,"یحییٰ بن قزعہ از ابراہیم بن سعد کی سند سے بھی یہ متن مروی ہے۔"],[157,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ ایک آدمی نے آکر پوچھا: ’’اے اللہ کے نبی! کون سے اعمال افضل ہیں؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ پر ایمان لانا۔۔۔‘‘ باقی الفاظ پچھلی حدیث والے ہیں۔","",{"k":"مصنف عبد الرزاق (11/190 – 191)۔ صحیح مسلم (83)"}],[158,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم سے پوچھا گیا: ’’یارسول اللہ! کون سے اعمال افضل یا بہتر ہیں؟‘‘ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ اور اس کے رسول پر ایمان لانا۔‘‘","",{"k":"مسند أحمد (2/287)۔ سنن الترمذي (1658)۔ مصنف ابن أبي شیبۃ (5/301)"}],[159,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم فرمایا کرتے تھے: ’’اللہ تعالیٰ کے نزدیک بہترین عمل ایسا ایمان ہے جس میں شک نہ ہو، ایسا جہاد ہے جس میں حاصل کردہ مال غنیمت میں خیانت نہ ہو اور ایسا حج ہے جو شرعی تقاضوں کے مطابق ہو۔‘‘"],[160,"موسیٰ از ابان کی سند سے بھی یہی متن مروی ہے۔"],[161,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا کہ ’’اللہ کے نزدیک بہترین عمل ایسا ایمان ہے جس میں شک نہ ہو،۔۔۔‘‘ باقی الفاظ پچھلی حدیث والے ہیں۔","",{"k":"مسند أحمد (2/348، 442، 521)۔ مسند أبي داود الطیالسي (2518)۔ صحیح ابن حبان (4597)"}],[162,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا: ’’کون سا عمل بہترین ہے؟ ‘‘ فرمایا: ’’اللہ پر ایمان اور فی سبیل اللہ جہاد۔‘‘"],[163,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم کے پاس ایک آدمی آیا اور پوچھنے لگا: ’’کون سا عمل افضل ہے؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ پر ایمان اور فی سبیل اللہ جہاد۔‘‘","",{"k":"مسند أحمد (2/388، 531)"}],[164,"سیدنا ابو ذر رضی اللہ عنہ سے روایت ہے، کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: ’’کون سا عمل افضل ہے؟‘‘ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ پر ایمان اور فی سبیل اللہ جہاد۔‘‘","",{"k":"صحیح البخاري (2518)۔ صحیح مسلم (84)"}],[165,"سیدنا ابو ذر رضی اللہ عنہ بیان کرتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: ’’کون سا عمل بہترین ہے؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ پر ایمان اور فی سبیل اللہ جہاد۔‘‘"],[166,"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا (وفات: 57ھ)بیان کرتی ہیں کہ ایک آدمی نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور پوچھنے لگا: ’’کون سا عمل افضل ہے؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ پر ایمان، فی سبیل اللہ جہاد اور حج مبرور۔‘‘","",{"k":"سنن سعید بن منصور (2/165 – 166)"}],[167,"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم سے پوچھا گیا: ’’کون سا عمل افضل ہے؟‘‘ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ پر ایمان، فی سبیل اللہ قتال اور حج مبرور۔‘‘"],[168,"سیدہ شفاء رضی اللہ عنہا بیان کرتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایک آدمی کے سوال’’کون سا عمل افضل ہے؟‘‘ کا جواب دیتے ہوئے سنا، آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ پر ایمان، جہاد اور حج مبرور۔‘‘","",{"k":"مسند أحمد (6/372)۔ مسند أبي عوانۃ (4/515)۔ مسند إسحاق بن راھویہ (1/99)"}],[169,"سیدنا عبادہ بن صامت رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم سے پوچھا گیا: ’’کون سا عمل افضل ہے؟‘‘ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ پر ایمان، اس کے رسول کی تصدیق اور فی سبیل اللہ جہاد۔‘‘","",{"k":"مسند أحمد (5/318)۔ کتاب الجھاد لابن أبي عاصم (1/177)۔ شعب الإیمان للبیھقي (7/232)"}],[170,"سیدنا عبد اللہ بن حُبْشِی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’افضل عمل ایسا ایمان ہے جس میں کوئی شک نہ ہو۔‘‘","",{"k":"سنن أبي داود: 2/146، رقم: 1449۔ سنن النسائي: 5/58۔ مسند أحمد: 3/411 – 412۔ اس حدیث کی سند کے صحیح یا ضعیف ہونے میں اختلاف ہے لیکن اس کے شواہد موجود ہیں۔"}],[171,"سیدنا عبادہ بن صامت رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے یہ سوال ہوتے ہوئے سنا کہ کون سا عمل افضل ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ پر ایمان اور اس کی کتاب کی تصدیق۔‘‘","",{"k":"کتاب الجھاد لابن أبي عاصم (1/177)"}],[172,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’مذکورہ بالا احادیث میں رسول اللہ صلی اللہ علیہ وسلم نے ایمان، تصدیق، جہاد اور بھلائی سب کو عمل قرار دیا ہے۔‘‘","",{"k":"اسی وجہ سے امام بخاری رحمہ اللہ نے نمبر 153 تا 171 ابو ہریرہ وغیرہ صحابہ رضی اللہ عنہم کی روایات نقل کی ہیں۔"}],[173,"نبی کریم صلی اللہ علیہ وسلم کا فرمان گرامی ہے: ’’ایک قوم ظاہر ہوگی جس کے اعمال کے سامنے تم اپنے اعمال کو حقیر سمجھو گے۔ وہ قرآن پڑھیں گے۔‘‘ اس فرمان میں آپ صلی اللہ علیہ وسلم نے واضح فرما دیا ہے کہ قرآن کریم کی تلاوت ایک عمل ہے۔","",{"k":"امام بخاری رحمہ اللہ یہ کہنا چاہ رہے ہیں کہ جب قراءتِ قرآن ایک عمل ہے تو جسے پڑھا جاتا ہے یعنی قرآن،قراءت سے الگ چیز ہے۔"}],[174,"سیدنا ابو سعید خدری رضی اللہ عنہ نے بیان کیا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں ایک قوم ایسی پیدا ہو گی کہ تم اپنی نماز کو ان کی نماز کے مقابلہ میں حقیر سمجھو گے، اور ان کے عمل کے مقابلہ میں تمہیں اپنا عمل حقیر نظر آئے گا۔ وہ قرآن مجید کی تلاوت بھی کریں گے لیکن قرآن مجید ان کے حلق سے نیچے نہیں اترے گا۔ دین سے وہ اس طرح نکل جائیں گے جیسے تیر کمان سے نکل جاتا ہے۔‘‘","",{"k":"صحیح البخاري (3344)۔ صحیح مسلم (1064)"}],[175,"عبد اللہ بن یوسف از مالک کی سند سے بھی یہ متن مروی ہے۔"],[176,"قتادہ رحمہ اللہ آیت کریمہ:\n﴿ وَجَعَلُواْ لَهُۥ مِنۡ عِبَادِهِۦ جُزۡءًاۚ ﴾ [الزخرف: ۱۵]\n’’اور ان (مشرک) لوگوں نے اللہ کے بندوں میں سے بعض کو اس کا جزو بنا ڈالا۔‘‘\nکی وضاحت کرتے ہوئے فرماتے ہیں: ’’یعنی اللہ کے برابر کا بنا لیا ہے۔‘‘","",{"k":"تفسیر ابن جریر: 25/56۔ تفسیر عبد الرزاق الصنعاني: 3/195) امام بخاری رحمہ اللہ اس آیت کو پیش کرکے یہ کہنا چاہ رہے ہیں کہ مشرکوں کا کہنا: ’’اللہ کی اولاد ہے‘‘ یا ’’فرشتے اللہ کی بیٹیاں ہیں‘‘ یہ ان کا فعل ہے اور فرشتے اللہ کے بندے اور اس کی مخلوق ہیں، اسی وجہ سے اللہ تعالیٰ نے ان کے فعل کو ’’جعل‘‘ سے تعبیر کیا ہے اور اس کی نسبت انہی کی طرف کی ہے۔ بندے کا قرآن کی تلاوت کرنے کا معاملہ بھی یہی ہے کہ قراءت بندے کا فعل ہے جو اللہ کا پیدا کردہ ہے جبکہ قرآن کلام اللہ ہے، مخلوق نہیں ہے۔دیکھیے: مجموع الفتاوی: 17/271"}],[177,"حماد بن زید رحمہ اللہ کا فرمان ہے: ’’جو شخص اس بات کا قائل ہے کہ بندوں کا کلام مخلوق نہیں ہے، وہ کافر ہے۔‘‘","",{"k":"اس کی سند پوائنٹ نمبر: 642 میں آئے گی۔"}],[178,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’اللہ تعالیٰ جب چاہتے ہیں، کلام کرتے ہیں اور بندوں کی آوازیں حروف سے مل کربنتی ہیں جس میں تطریب، ہمز، لحن اور ترجیع ہوتی ہے۔ (یعنی بندوں کی آوازیں کبھی باریک ہوتی ہیں، کبھی موٹی ہوتی ہیں اور کبھی ایک ہی لفظ کو دہرایا جارہا ہوتا ہے۔) اس کی دلیل نبی کریم صلی اللہ علیہ وسلم کی زوجہ مطہرہ سیدہ ام سلمہ رضی اللہ عنہا کی درج ذیل روایت ہے:"],[179,"یعلیٰ بن مملک سے روایت ہے کہ انہوں نے سیدہ ام سلمہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کی قراءت اور نماز کے بارے میں پوچھا تو انہوں نے کہا: ’’تم کہاں اور آپ صلی اللہ علیہ وسلم کی نماز کہاں؟ آپ نماز پڑھتے اور جتنی دیر پڑھتے، اتنا ہی دیر سوتے۔ پھر جتنا سو لیتے، اتنی دیر نماز پڑھتے۔ پھر جتنی دیر نماز پڑھتے، اتنی دیر سوتے یہاں تک کہ صبح ہو جاتی۔‘‘ پھر ام سلمہ رضی اللہ عنہا نے آپ صلی اللہ علیہ وسلم کی قراءت بیان کی تو وہ ایک ایک حرف الگ الگ پڑھ رہی تھیں۔‘‘","",{"k":"سنن أبي داود (1466)۔ سنن النسائي (2/181)۔ سنن الترمذي (2923)"}],[180,"قتیبہ از لیث از عبد اللہ بن عبید اللہ بن ابی ملیکہ کی سند سے بھی یہ متن منقول ہے۔"],[181,"عمران بن عبد اللہ کہتے ہیں کہ ماہِ رمضان میں مسجد نبوی میں ایک شخص نے ہمیں نماز پڑھائی اور بڑی لَے کے ساتھ گانے کے انداز میں قراءت کی۔ قاسم بن محمد (ابن ابو بکر صدیق رضی اللہ عنہ) نے اس پر اعتراض کیا اور کہا کہ اللہ تعالیٰ کا فرمان ہے:\n﴿ وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزٌ ٤١ لَّا يَأۡتِيهِ ٱلۡبَٰطِلُ مِنۢ بَيۡنِ يَدَيۡهِ وَلَا مِنۡ خَلۡفِهِۦۖ تَنزِيلٌ مِّنۡ حَكِيمٍ حَمِيدٍ ﴾ [فصلت: ۴۱ - ۴۲]\n’’اور بلاشبہ یہ ایک باعزت کتاب ہے۔ جس تک باطل کی کوئی رسائی نہیں ہے نہ اس کے آگے سے نہ اس کے پیچھے سے یہ اس ذات کی طرف سے اتاری جا رہی ہے جو حکمت کا مالک ہے، تمام تعریفیں اسی کی طرف لوٹتی ہیں۔‘‘","",{"k":"شعب الإیمان للبیھقي (1965)۔ مصنف ابن أبي شیبۃ (10/465 – 466)۔ سنن الدارمي (2/564)"}],[182,"عبد اللہ بن عبد الرحمن بن ابی صعصعہ بیان کرتے ہیں کہ سیدنا ابو سعید خدری رضی اللہ عنہ نے ان سے کہا: ’’میں دیکھتا ہوں کہ تمہیں بکریوں سمیت جنگل میں رہنا پسند ہے۔ اس لیے جب تم جنگل میں اپنی بکریوں کو لیے ہوئے موجود ہو اور نماز کے لیے اذان دو تو بلند آواز سے اذان دیا کرو۔ کیونکہ جن و انس بلکہ تمام چیزیں جو مؤذن کی آواز سنتی ہیں، قیامت کے دن اس کے حق میں گواہی دیں گی۔‘‘ سیدنا ابوسعید رضی اللہ عنہ نے فرمایا کہ ’’یہ میں نے نبی کریم صلی اللہ علیہ وسلم سے سنا ہے۔‘‘","",{"k":"صحیح البخاري (609)"}],[183,"عبد اللہ بن یوسف از مالک کی سند سے بھی یہ متن مروی ہے۔"],[184,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: ’’مؤذن کی آواز جہاں تک جاتی ہے، اللہ تعالیٰ مؤذن کو بخش دیتے ہیں۔‘‘","",{"k":"یعنی اس کے اتنے گناہ بخش دیے جاتے ہیں جو اتنی جگہ میں سما سکیں۔یا اتنی زیادہ بخشش اسے عطاء فرماتے ہیں۔ یااذان کی لمبائی کے برابر اسے رحمت عطاء ہوتی ہے۔"}],[185,"سلیمان از شعبہ کی سند سے بھی یہ متن مروی ہے۔","",{"k":"سنن أبي داود (515)۔ سنن النسائي (2/13)۔ سنن ابن ماجہ (724)"}],[186,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’مؤذن کی جہاں تک آواز جاتی ہے، اس کی بخشش کردی جاتی ہے۔‘‘"],[187,"حفص بن عمر از شعبہ از موسیٰ از ابو یحییٰ کی سند سے بھی یہ متن مروی ہے۔"],[188,"سیدنا عبداللہ بن زید رضی اللہ عنہ کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم نے ناقوس کی تیاری کا حکم دینے کا ارادہ کیا تاکہ لوگوں کو نماز کی خاطر جمع ہونے کے لیے اسے بجایا جا سکے تو ایک رات میں نے خواب دیکھا کہ ایک شخص کے ہاتھ میں ناقوس ہے۔ میں نے اس سے پوچھا: ’’اللہ کے بندے! کیا اسے فروخت کرو گے؟‘‘ اس نے کہا: ’’تم اس کا کیا کرو گے؟‘‘ میں نے کہا: ’’ہم اس کے ذریعے لوگوں کو نماز کے لیے بلائیں گے۔‘‘ اس شخص نے کہا: ’’کیا میں تمہیں اس سے بہتر چیز نہ بتا دوں؟‘‘ میں نے کہا: ’’کیوں نہیں، ضرور بتائیے۔‘‘ تو اس نے کہا: ’’تم اس طرح کہو:\n«اَللهُ أَكْبَرُ اَللهُ أَكْبَرُ، اَللهُ أَكْبَرُ اَللهُ أَكْبَرُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، حَيَّ عَلَى الصَّلَاةِ، حَيَّ عَلَى الصَّلَاةِ، حَيَّ عَلَى الْفَلَاحِ، حَيَّ عَلَى الْفَلَاحِ، اَللهُ أَكْبَرُ، اَللهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللهُ»\n’’اللہ سب سے بڑا ہے، اللہ سب سے بڑا ہے، اللہ سب سے بڑا ہے، اللہ سب سے بڑا ہے۔ میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود برحق نہیں۔ میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود برحق نہیں۔ میں گواہی دیتا ہوں کہ محمد صلی اللہ علیہ وسلم اللہ کے رسول ہیں۔ میں گواہی دیتا ہوں کہ محمد صلی اللہ علیہ وسلم اللہ کے رسول ہیں۔ نماز کے لیے آؤ۔ نماز کے لیے آؤ۔ کامیابی کی طرف آؤ۔ کامیابی کی طرف آؤ۔ اللہ سب سے بڑا ہے، اللہ سب سے بڑا ہے۔ اللہ کے سوا کوئی معبود برحق نہیں۔‘‘\nعبداللہ بن زید رضی اللہ عنہ کہتے ہیں: پھر وہ شخص مجھ سے تھوڑا سا پیچھے ہٹا، لیکن زیادہ دور نہیں گیا، پھر اس نے کہا: ’’جب تم نماز کے لیے کھڑے ہو تو اس طرح کہو:\n«اَللهُ أَكْبَرُ اَللهُ أَكْبَرُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، حَيَّ عَلَى الصَّلَاةِ، حَيَّ عَلَى الْفَلَاحِ، قَدْ قَامَتِ الصَّلَاةُ، قَدْ قَامَتِ الصَّلَاةُ، اَللهُ أَكْبَرُ، اَللهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللهُ»\nجب صبح ہوئی تو میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور جو کچھ میں نے دیکھا تھا، اسے آپ سے بیان کیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ان شاءاللہ یہ خواب سچا ہے۔“ پھر فرمایا: ”تم بلال کے ساتھ کھڑے ہوجاؤ اور جو کلمات تم نے خواب میں دیکھے ہیں، وہ انہیں بتاتے جاؤ تاکہ وہ اس کے مطابق اذان دیں کیونکہ ان کی آواز تم سے بلند ہے۔“ چنانچہ میں بلال رضی اللہ عنہ کے ساتھ کھڑا ہوا، میں انہیں اذان کے کلمات بتاتا جاتا تھا اور وہ اسے پکارتے جاتے تھے۔ وہ کہتے ہیں: ’’عمر بن خطاب رضی اللہ عنہ نے اسے اپنے گھر میں سے سنا تو وہ اپنی چادر گھسیٹتے ہوئے نکلے اور کہہ رہے تھے: ’’اللہ کے رسول! اس ذات کی قسم! جس نے آپ کو حق کے ساتھ بھیجا ہے، میں نے بھی اسی طرح دیکھا ہے جس طرح عبداللہ رضی اللہ عنہ نے دیکھا ہے۔‘‘ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”الحمد للہ۔“","",{"k":"سنن أبي داود (499)۔ سنن الترمذي (189)۔ سنن ابن ماجہ (706)"}],[189,"محمد بن عبد اللہ بن زید بیان کرتے ہیں کہ عبد اللہ بن زید رضی اللہ عنہ نے (اذان کے بارے میں) خواب دیکھا تو انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے پاس جاکر وہ خواب آپ صلی اللہ علیہ وسلم کے گوش گزار کیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’بلال کے ساتھ جاؤ اور اسے اذان کے کلمات بتاؤ تاکہ وہ اذان دے کیونکہ اس کی آواز تم سے زیادہ بلند ہے۔‘‘ عبد اللہ کہتے ہیں کہ میں بلال رضی اللہ عنہ کے ساتھ مسجد میں گیا اور انہیں کلماتِ اذان بتانے لگا اور وہ اذان دینے لگے۔ عمر رضی اللہ عنہ نے جب یہ آواز سنی تو گھر سے باہر آئے اور آکر کہنے لگے: ’’یا رسول اللہ! اللہ کی قسم! میں نے بھی عبد اللہ جیسا خواب دیکھا ہے۔‘‘"],[190,"سیدنا ابو محذورہ رضی اللہ عنہ بیان کرتے ہیں کہ مجھے نبی کریم صلی اللہ علیہ وسلم نے فرمایا: «أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ.، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ» کو لمبا کرکے پڑھو۔","",{"k":"سنن أبي داود: 1/340، رقم: 500۔ سنن النسائي: 2/423۔ سنن الترمذي: 1/366، رقم: 191 مختصراً"}],[191,"نبی کریم صلی اللہ علیہ وسلم کا فرمان گرامی ہے: ’’جب تم اذان سنو تو جیسے مؤذن کہہ رہا ہے، ویسے ہی تم بھی کہو۔‘‘","",{"k":"صحیح البخاري (611)۔ صحیح مسلم (383)"}],[192,"ابو محذورہ رضی اللہ عنہ نے جب خوبصورت آواز نکالی تو عمر رضی اللہ عنہ نے ان سے کہا: ’’کیا آپ کو ڈر نہیں لگا کہ آپ کا پیٹ پھٹ جائے گا؟‘‘ تو ابو محذورہ رضی اللہ عنہ نے جواب دیا:’’میں نے تو آپ کےلیے اپنی آواز کو خوبصورت بنایا تھا۔‘‘","",{"k":"مصنف عبد الرزاق: 1/482، 545۔ اس کی سند منقطع ہے کیونکہ خالد بن عکرمہ کا عمر سے سماع نہیں ہے۔ یہ روایت متصل سند سے مصنف عبد الرزاق: 4/14 میں ہے۔"}],[193,"سیدنا عمر بن عبد العزیز رحمہ اللہ (المتوفیٰ: 101ھ) نے (اپنے مؤذن سے) کہا کہ سیدھی سادی اذان دیا کرو، ورنہ ہم سے الگ ہو جاؤ۔","",{"k":"صحیح البخاري: 2/87 معلقاً۔ مصنف ابن أبي شیبۃ: 1/229"}],[194,"عروہ بن زبیر رحمہ اللہ بیان کرتے ہیں کہ ام المؤمنین سیدہ عائشہ رضی اللہ عنہا عثمان بن عفان رضی اللہ عنہ کے ساتھ پیش آنے والا معاملہ یاد کرکے فرمایا کرتی تھیں: ’’اے کاش! میں بھولی بسری ہوتی۔ اللہ کی قسم! مجھے کسی بھی معاملہ میں عثمان رضی اللہ عنہ کی بے حرمتی پسند نہیں تھی۔ مگر جو کچھ بھی ہوا، مجھے لگا کہ وہ میرے ساتھ ہوا ہے۔ یہاں تک کہ اللہ کی قسم! اگر میں انہیں شہید کرنا پسند کرتی تو مجھے ہی قتل کردیا جاتا۔ اے عبید اللہ بن عدی! یہ بات جان لینے کے بعد کوئی تجھے بالکل بھی دھوکے میں نہ ڈالے۔ اللہ کی قسم! اصحابِ رسول کے اعمال کو کبھی کمترنہیں سمجھا گیا تھا، یہاں تک کہ وہ جماعت ظاہر ہوئی جنہوں نے عثمان رضی اللہ عنہ کے متعلق طعن وتشنیع کی۔ انہوں نے ایسی بات کی کہ اس جیسی اچھی بات کسی نے نہیں کہی۔ انہوں نے (قرآن کی) اس طرح قراءت کی کہ اس جیسی اچھی قراءت کسی نے نہیں کی۔ اور انہوں نے اس انداز میں نماز پڑھی کہ اس جیسی نماز نہیں پڑھی گئی۔ پھر جب میں نے (ان کے) کرتوتوں کو غور سے دیکھا تو تب مجھے اندازہ ہوا کہ اللہ کی قسم! یہ تو اصحاب ِ رسول کے اعمال کے قریب بھی نہیں ہیں۔ تو جب تمہیں کسی آدمی کی اچھی بات بھلی لگے تو تم یوں کہو:\n﴿ ٱعۡمَلُواْ فَسَيَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ ﴾ [التوبۃ: ۱۰۵]\n’’عمل کرتے رہو۔ عنقریب اللہ، اس کے رسول تمہارا عمل دیکھ لیں گے۔‘‘\nاور کسی کا نیک عمل تمہیں بالکل بھی دھوکے میں نہ ڈالے۔‘‘","",{"k":"مصنف عبد الرزاق (11/447)۔ تفسیر ابن أبي حاتم (6/1877)۔ الرد علی الجھمیۃ لعثمان بن سعید (83)"}],[195,"امام بخاری رحمہ اللہ فرماتے ہیں کہ جبریل علیہ السلام نے آپ صلی اللہ علیہ وسلم سے جب ایمان کے متعلق سوال کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تو اللہ پر، اس کے فرشتوں پر، اس کی کتابوں پر اور اس کے رسولوں پر ایمان لائے۔‘‘ جبریل علیہ السلام نے پوچھا: ’’جب میں یہ کرلوں گا تو میں مؤمن ہوں گا؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جی ہاں!‘‘ پھر انہوں نے پوچھا: ’’اسلام کیا ہے؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تم اس بات کی گواہی دو کہ اللہ کے علاوہ کوئی معبودِ حقیقی نہیں ہے اور میں اللہ کا رسول ہوں۔۔۔‘‘ آپ صلی اللہ علیہ وسلم نے پوری بات بتائی۔جبریل علیہ السلام نے پوچھا: ’’جب میں یہ کرلوں گا تو میں مسلمان ہوں گا؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جی ہاں!‘‘"],[196,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’رسول اللہ صلی اللہ علیہ وسلم نے اس حدیث میں ایمان، اسلام، گواہی، احسان اور نماز میں قراءت اور دیگر حرکات مثلاً رکوع اور سجدہ وغیرہ، سب کو بندہ کا فعل قرار دیا ہے۔‘‘"],[197,"فرمان باری تعالیٰ ہے:\n﴿ شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلۡمَلَٰٓئِكَةُ وَأُوْلُواْ ٱلۡعِلۡمِ قَآئِمَۢا بِٱلۡقِسۡطِۚ ﴾ [آل عمران: ۱۸]\n’’اللہ نے خود اس بات کی گواہی دی ہے، اور فرشتوں اور اہل علم نے بھی کہ اس کے سوا کوئی معبود نہیں جس نے انصاف کے ساتھ (کائنات) کا انتظام سنبھالا ہوا ہے۔‘‘"],[198,"سیدنا ابو ذر اور ابو ہریرہ رضی اللہ عنہما سے روایت ہے، دونوں کہتے ہیں کہ ایک آدمی آیا اور اس نے کہا: ’’السلام علیکم یا محمد!‘‘ آپ صلی اللہ علیہ وسلم نے اس کے سلام کا جواب دیا۔ پھر اس نے پوچھا: ’’اے محمد! ایمان کیا ہے؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ کو، اس کے فرشتوں کو، کتاب کو اور نبیوں کو ماننا اور ہر طرح کی تقدیر کو تسلیم کرنا۔‘‘اس نے کہا: ’’اگر میں یہ کر گزروں تو میں مؤمن ہوں گا؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جی ہاں!‘‘","",{"k":"صحیح البخاري (50)۔ صحیح مسلم (1029)۔ سنن أبي داود (4698)"}],[199,"سیدنا عمر رضی اللہ عنہ بیان کرتے ہیں کہ ایک مرتبہ ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر تھے کہ ایک آدمی آیا اور کہنے لگا: ’’یا رسول اللہ! اسلام کیا ہے؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ کہ تم اپنے آپ کو اللہ کا فرمانبردار بنا لو، نماز قائم کرو، زکاۃ ادا کرو، رمضان کے روزے رکھو اور بیت اللہ کا حج کرو۔‘‘ اس نے کہا: ’’مجھے اسلام کی کڑیوں کے بارے میں بتائیے۔‘‘ آپ صلی اللہ علیہ وسلم نے اسے بتایا۔\nآخر میں اس نے کہا: ’’جب میں یہ سارے کام کرلوں تو میں مسلمان ہوں گا؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جی ہاں!‘‘ اس نے کہا: ’’آپ نے سچ کہا۔‘‘ پھر راوی نے مکمل حدیث بیان کی۔","",{"k":"صحیح مسلم: 1/38 بعد رقم: 8"}],[200,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ ایک مرتبہ نبی کریم صلی اللہ علیہ وسلم اپنے صحابہ کرام رضی اللہ عنہم کے ساتھ تشریف فرما تھے کہ ایک آدمی آیا جس نے سفری کپڑے پہن رکھے تھے۔ وہ لوگوں کی گردنیں پھلانگتا ہوا آپ صلی اللہ علیہ وسلم کے سامنے بیٹھ گیا اور اپنے ہاتھوں کو آپ صلی اللہ علیہ وسلم کے گھٹنوں پر رکھ کر پوچھنے لگا: ’’اسلام کیا ہے؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’کلمہ طیبہ کی گواہی دینا، نماز قائم کرنا، زکاۃ ادا کرنا، رمضان کے روزے رکھنا اور اگر بیت اللہ تک جانے کی استطاعت ہو تو حج کرنا۔‘‘ اس نے کہا: ’’جب میں یہ سارے کام کرلوں تو میں مؤمن ہوں گا؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جی ہاں!‘‘ کہنے لگا: ’’آپ سچ فرما رہے ہیں۔‘‘ صحابہ کرام رضی اللہ عنہم کو اس کی بات پر تعجب ہوا۔ پھر وہ پوچھنے لگا: ’’احسان کیا ہے؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تم اللہ سے ڈرو گویا کہ اللہ کو دیکھ رہے ہو۔ اگر تم نہیں دیکھ رہے تو وہ تمہیں دیکھ رہا ہے۔‘‘اس نے پوچھا: ’’قیامت کب آئے گی؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’مسؤول (جس سے پوچھا گیا ہے) کو سائل (پوچھنے والے)سے زیادہ علم نہیں ہے۔ لیکن اس کی کچھ نشانیاں ہیں۔‘‘ پھر وہ اٹھ کر چل دیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اس بندے کو پکڑ کر میرے پاس لاؤ۔‘‘ صحابہ اس کے پیچھے گئے لیکن وہ نہ ملا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ جبرائیل علیہ السلام تھے جو تمہیں تمہارا دین سکھانے آئے تھے۔ آج سے پہلے یہ اس طرح اجنبی بن کر نہیں آئے تھے کہ میں بھی پہچان نہ سکا۔‘‘","",{"k":"تعظیم قدر الصلاۃ للمروزي (1/389)۔ کشف الأستار للبزار (1/20 – 21)"}],[201,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ جس رات نبی کریم صلی اللہ علیہ وسلم کو معراج کروایا گیا تو جبار تبارک وتعالیٰ نے فرمایا: ’’اے محمد! میرے نزدیک بات تبدیل نہیں ہوتی ہے۔ میں نے تم پر (پچاس نمازیں) فرض کی ہیں جو لوح محفوظ میں لکھی ہیں۔ (اگرچہ اب پانچ کردی ہیں لیکن) ایک نیکی کا ثواب دس گنا ملتا ہے، اس اعتبار سے (پانچ نمازوں کا ثواب) پچاس کے برابر ہے۔‘‘","",{"k":"88 نمبر میں اس کی تخریج گزر چکی ہے۔"}],[202,"سیدنا معاویہ بن حکم رضی اللہ عنہ بیان کرتے ہیں کہ میں نے کہا: ’’یا رسول اللہ! ہم ابھی نئے نئے جاہلیت کو چھوڑ کر آئے ہیں اور اللہ تعالیٰ نے ہمیں اسلام کی دولت سے مالا مال کیا ہے۔۔۔۔‘‘ ایک دفعہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھ رہا تھا کہ کسی نمازی کو چھینک آگئی۔ میں نے کہا: ’’یَرْحَمُكَ اللہُ‘‘ ’’اللہ تم پر رحم کرے۔‘‘ جب نبی کریم صلی اللہ علیہ وسلم نماز سے فارغ ہوئے تو آپ صلی اللہ علیہ وسلم نے مجھے بلایا اور فرمایا: ’’ہماری اس نماز میں لوگوں کی باتوں میں سے کوئی بات کرنا درست نہیں ہے۔ نماز تو تسبیح، تکبیر اور قراءتِ قرآن کا نام ہے۔‘‘","",{"k":"صحیح مسلم (537)"}],[203,"سیدنا طارق المحاربی رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ صلی اللہ علیہ وسلم بآواز بلند کہہ رہے تھے: ’’لوگو! لا الٰہ الا اللہ کا اقرار کرلو، کامیاب ہوجاؤ گے۔‘‘","",{"k":"الزھد لابن المبارك، ص: 410، رقم: 1164۔ مصنف ابن أبي شیبۃ: 14/300۔ صحیح ابن خزیمۃ: 1/82، رقم: 159یہاں اس حدیث کو بیان کرنے کا مقصد یہ ہے کہ آپ صلی اللہ علیہ وسلم نے کامیابی کو کلمہ کے اقرار سے مشروط کیا ہے تو اس سے معلوم ہوتا ہے کہ کلمہ پڑھنا بندے کا فعل ہے۔"}],[204,"نبی کریم صلی اللہ علیہ وسلم نے عبد القیس قبیلہ کے اشج (منذر بن عائذ) سے فرمایا تھا: ’’تمہارے اندر دو ایسی خصلتیں ہیں جنہیں اللہ تعالیٰ پسند فرماتے ہیں، ایک حوصلہ وبردباری اور دوسری حیاء۔‘‘ انہوں نے پوچھا: ’’کیا یہ دونوں خصلتیں میری فطرت ہیں یا میرا اخلاق ہیں؟‘‘ تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تمہاری فطری خصلتیں ہیں۔‘‘ اس پر انہوں نے کہا: ’’الحمد للہ کہ اللہ نے مجھے فطرتاً ایسی خصلتیں عطا فرمائی ہیں۔‘‘"],[205,"قبیلہ عبد القیس کے اشج کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے ان سے مذکورہ بالا بات کہی تو میں نے پوچھا: ’’یہ خصلتیں پرانی ہیں یا نئی؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’پرانی۔‘‘","",{"k":"الأدب المفرد للبخاري، ص: 205، رقم: 284۔ السنن الکبری للنسائي: 4/416، رقم: 7746۔ مسند أحمد: 4/205 – 206۔ سند منقطع ہے کیونکہ ابن ابی بکرہ نے اشج عبد القیس کو نہیں پایا۔"}],[206,"عبد القیس کے اشج کہتے ہیں کہ جب نبی کریم صلی اللہ علیہ وسلم نے میرے بارے میں مذکورہ بالا بات ارشاد فرمائی تو میں نے کہا: ’’تمام تعریفیں اس للہ کے لیے ہیں جس نے مجھے فطرتاً ان خصلتوں سے نوازا جنہیں اللہ تعالیٰ پسند کرتے ہیں۔‘‘","",{"k":"مسند أحمد (4/205)۔ السنن الکبری للنسائي (4/416)۔ السنۃ لابن أبي عاصم (190)"}],[207,"اسماعیل بن موسیٰ از ہشیم از یونس از عبد الرحمن بن ابی بکرہ از اشج کی سند سے بھی یہ متن مروی ہے۔"],[208,"سیدنا عبد اللہ بن عمرو بن العاص رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کسی کوبیوی، لونڈی، سواری یا بیٹا نصیب ہوتو وہ یہ دعا کرے: ’’اے اللہ! میں اس کی بھلائی اور جس فطرت پر تو نے اسے پیدا کیا ہے، اس کی بھلائی کا سوال کرتا ہوں اور اس کے شر اور اس کی فطرت کے شر سے تیری پناہ میں آتا ہوں۔‘‘","",{"k":"عمل الیوم واللیلۃ للنسائي (ص 92)۔ المستدرك للحاکم (2/185 – 186)۔ سنن أبي داود (2160)"}],[209,"عبید اللہ از سفیان از ابن عجلان از عمرو کی سند سے بھی یہ متن منقول ہے۔","",{"k":"سنن ابن ماجہ (1918)"}],[210,"سیدنا ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اے اشج! تمہارے اندر دو ایسی خصلتیں ہیں جنہیں اللہ تعالیٰ پسند کرتا ہے: ایک تو حلم و بردباری، دوسری طمانینت و سہولت۔ اشج رضی اللہ عنہ نے پوچھا: ’’اللہ کے رسول! یہ صفات میری خلقت میں ہیں یا بعد میں پیدا ہوئی ہیں؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ”نہیں، یہ پیدائشی ہیں۔“","",{"k":"سنن ابن ماجہ (4187)۔ صحیح مسلم (17)"}],[211,"سیدنا مَزِیْدَہ العبدی رضی اللہ عنہ بیان کرتے ہیں کہ قبیلہ عبد القیس کا سردار اشج جب نبی صلی اللہ علیہ وسلم کے پاس آیا تو آپ صلی اللہ علیہ وسلم نے اسے فرمایا: ’’تمہارے اندر دو ایسی خصلتیں ہیں جو اللہ تعالیٰ کو محبوب ہیں۔‘‘ انہوں نے پوچھا: ’’یہ خصلتیں پیدائشی ہیں یا بعد میں میرے اخلاق کا حصہ بنی ہیں؟‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’پیدائشی ہیں۔‘‘ اس پر انہوں نے کہا: ’’اللہ کا شکر ہے کہ اس نے میری پیدائشی خصلتیں ایسی بنائی ہیں کہ جو اللہ اور اس کے رسول کو محبوب ہیں۔‘‘","",{"k":"الأدب المفرد للبخاري (587)۔ المعجم الکبیر للطبراني (20/346)۔ مسند أبي یعلیٰ (12/245 – 247)"}],[212,"سیدنا زارع بن عامر رضی اللہ عنہ بیان کرتے ہیں کہ وہ آپ صلی اللہ علیہ وسلم کے پاس گئے۔ آپ نے فرمایا: ’’اے اشج! بلکہ اللہ نے پیدائشی طور پر تمہارے اندر یہ خصلتیں رکھی ہیں۔‘‘ اس پر انہوں نے کہا: ’’اللہ تیرا شکر ہے۔‘‘","",{"k":"سنن أبي داود: 5/395، رقم: 5225۔ المعجم الکبیر للطبراني: 5/275۔ ان احادیث سے امام بخاری رحمہ اللہ کا استدلال یہ ہے کہ بندے کی ساری صفات، اخلاق اور افعال اللہ تعالیٰ کے پیدا کردہ ہیں کیونکہ آپ صلی اللہ علیہ وسلم نے فرمایا تھا: ’’بلکہ تمہاری یہ خصلتیں پیدائشی ہیں۔"}],[213,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’قرآن کے صفتِ باری تعالیٰ ہونے کے علاوہ کوئی توجیہ نہیں کی جاسکتی۔ اس پر یہ اعتراض نہ کیا جائے کہ قرآن کی یہ توجیہ کیسے ہوسکتی ہے کیونکہ یہ رب تعالیٰ کا کلام ہے جو اس نے بندوں کی زبانوں سے جاری کروایا ہے۔ اسی طرح نبی کریم صلی اللہ علیہ وسلم سے متواتر احادیث منقول ہیں کہ قرآن کلام اللہ ہے اور اللہ کا حکم اس کے کسی چیز کو پیدا کرنے سے پہلے موجود ہوتا ہے۔ کتاب اللہ بھی یہی کہتی ہے۔‘‘"],[214,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’کیا کوئی شخص مجھے اپنی قوم تک لے جائے گا؟ کیونکہ قریش نے مجھے میرے رب کے کلام کی تبلیغ سے روک دیا ہے۔‘‘","",{"k":"پوائنٹ نمبر 87 میں اس کا حوالہ گزر چکا ہے۔"}],[215,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’مذکورہ حدیث میں نبی کریم صلی اللہ علیہ وسلم نے یہ بات واضح فرما دی ہے کہ آپ صلی اللہ علیہ وسلم کی ذمہ داری تبلیغ کرنا تھا جبکہ کلام تو اللہ تعالیٰ کا تھا۔"],[216,"مہاجرین وانصار اور نیکی کے ساتھ ان کی پیروی کرنے والوں سے ہماری ذکر کردہ بات کے خلاف کچھ بھی منقول نہیں ہے۔ حالانکہ یہی وہ لوگ ہیں جنہوں نے نبی کریم صلی اللہ علیہ وسلم کے بعد ہر دور میں کتاب وسنت کی تبلیغ کی ہے۔ فرمان باری تعالیٰ ہے:\n﴿ لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيۡكُمۡ شَهِيدًاۗ ﴾ [البقرۃ: ۱۴۳]\n’’تاکہ تم دنیا کے لوگوں پر گواہ ہو اور رسول تم پر گواہ ہو۔‘‘"],[217,"نبی اکرم صلی اللہ علیہ وسلم کا فرمان ہے: ’’تم لوگ زمین میں اللہ تعالیٰ کے گواہ ہو۔‘‘","",{"k":"صحیح البخاري: 3/228، رقم: 1367۔ صحیح مسلم: 2/655، رقم: 949 عن أنس رضي اللہ عنہ"}],[218,"سیدنا ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”قیامت کے دن نوح علیہ السلام بارگاہ الٰہی میں حاضر ہوں گے۔ اللہ تعالیٰ دریافت فرمائے گا: ’’کیا (میرا پیغام) تم نے پہنچا دیا تھا؟‘‘ نوح علیہ السلام عرض کریں گے: ’’اے رب العزت!میں نے تیرا پیغام پہنچا دیا تھا۔‘‘ اب اللہ تعالیٰ ان کی امت سے دریافت فرمائے گا: ’’کیا (نوح علیہ السلام نے) تم تک میرا پیغام پہنچا دیا تھا؟‘‘ وہ جواب دیں گے: ’’نہیں، ہمارے پاس تیرا کوئی نبی نہیں آیا۔‘‘ اس پر اللہ تعالیٰ نوح علیہ السلام سے دریافت فرمائے گا: ’’آپ کی طرف سے کوئی گواہی دے سکتا ہے؟‘‘ وہ عرض کریں گے کہ محمد صلی اللہ علیہ وسلم اور ان کی امت (کے لوگ میرے گواہ ہیں۔) چنانچہ تمہیں حاضر کیا جائے گا اور تم اس بات کی گواہی دو گے کہ نوح علیہ السلام نے اللہ تعالیٰ کا پیغام اپنی قوم تک پہنچایا تھا اور یہی مفہوم اللہ جل ذکرہ کے اس ارشاد کا ہے:\n﴿ وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةً وَسَطًا لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيۡكُمۡ شَهِيدًاۗ ﴾ [البقرۃ: ۱۴۳]\n”اور اسی طرح ہم نے تمہیں امت وسط بنایا، تاکہ تم لوگوں پر گواہی دو اور رسول تم پر گواہی دے۔“\nاور «وَسَطٌ» کے معنی ’’عادل‘‘ کے ہیں۔","",{"k":"صحیح البخاري (3339)۔ مسند أحمد (3/32)"}],[219,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’اس سے وہ لوگ مراد ہیں جن کے بارے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا: ’’میری امت میں سے ایک گروہ ہمیشہ حق پر غالب رہے گا۔ جو انہیں چھوڑے گا، وہ انہیں کوئی نقصان نہیں پہنچا سکے گا۔‘‘"],[220,"سیدنا مغیرہ بن شعبہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’میری امت میں سے ایک گروہ ہمیشہ غالب رہے گا۔ یہاں تک کہ جب اللہ کا فیصلہ آجائے گا تو وہ غالب ہی ہوں گے۔‘‘","",{"k":"صحیح البخاري (3640)۔ صحیح مسلم (1921)"}],[221,"امام بخاری رحمہ اللہ فرماتے ہیں کہ اسی طرح کے الفاظ سیدنا ابو ہریرہ، معاویہ، جابر، سَلَمہ بن نُفَیْل اور قُرَّہ بن اِیَّاس رضی اللہ عنہم نے بھی نبی کریم صلی اللہ علیہ وسلم سے روایت کیے ہیں۔","",{"k":"حدیث ابو ہریرہ کےلیے دیکھیے: سنن ابن ماجہ (7)۔ مسند أحمد: 2/321۔ صحیح ابن حبان: 6835۔ حدیث معاویہ کےلیے دیکھیے: صحیح البخاري (3641)۔ صحیح مسلم (1037)۔ حدیث جابر کےلیے دیکھیے: صحیح مسلم (1923)۔ سلمہ بن نفیل کی حدیث کےلیے دیکھیے: سنن النسائي: 6/214 – 215۔ مسند أحمد: 4/104۔ قرہ بن ایاس کی حدیث کےلیے دیکھیے: سنن الترمذي (2192)۔ سنن ابن ماجہ (6)، مسند أحمد: 3/436۔ یہ حدیث درج ذیل صحابہ سے بھی مروی ہے۔ عقبہ بن عامر سے صحیح مسلم (1924) میں ہے۔ ثوبان سے صحیح مسلم (1920) میں ہے۔ جابر بن سمرہ سے مسلم (1922) میں ہے۔ عمران بن حصین سے مسند أحمد: 5/429، 437 میں ہے اور ابو امامہ سے مسند أحمد: 5/269 میں ہے۔ اہل علم نے اس حدیث کو متواتر قرار دیا ہے۔ مثلاً شیخ الاسلام ابن تیمیہ نے اقتضاء الصراط المستقیم: 1/69 میں، سیوطی نے قطف الأزھار المتناثرۃ في الأحادیث المتواترۃ، ص: 216 میں، زبیدی نے اللآلیء المتناثرۃ في الأحادیث المتواترۃ، ص: 68 میں اور کتانی نے نظم المتناثر في الحدیث المتواتر، ص: 93 میں اسے متواتر کہا ہے۔"}],[222,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’اس مسئلہ میں اہل علم کے درمیان مالک، ثوری، حماد بن زید اور علماء ِ امصار کے زمانے تک کوئی اختلاف نہیں تھا۔ ان کے بعد اہل حجاز میں سے ابن عیینہ، محدثینِ اہل بصرہ میں سے یحییٰ بن سعید، عبد الرحمن بن مہدی، عبد اللہ بن ادریس، حفص بن غیاث، ابو بکر بن عیاش، وکیع اور ان کے ساتھی اور عبد اللہ بن مبارک اور ان کے پیروکار، اور علماء واسط میں سے یزید بن ہارون سے لے کر ہمارے زمانے تک اہل حرمین یعنی مکہ ومدینہ، اہل عراقین، اہل شام، اہل مصر اور محدثینِ اہل خراسان جن میں محمد بن یوسف اور ان کے ساتھی ہیں، اسی طرح ابو الولید ہشام بن عبد الملک اور ان کے خاص لوگ، اسماعیل بن ابی اویس اہل مدینہ کے ساتھ، ابو مُسْہِر اہل شام میں سے اور نُعَیْم بن حماد مصریوں سمیت اور احمد بن حنبل اہل بصرہ سمیت اور اہلِ قریش سے حُمَیدی اور اہل مکہ میں سے رسول اللہ صلی اللہ علیہ وسلم کے پیروکار اور اسحاق بن ابراہیم اور اہل لغت میں سے ابو عُبَیْد شامل ہیں۔"],[223,"اپنے اپنے زمانے کے یہ تمام معروف اہل علم اس مسئلہ میں یک زبان تھے کہ قرآن کلام اللہ ہے۔ البتہ چند علماء نے بھول کر یا واضح راستے سے غفلت کی بناء پر شذوذ کی راہ اختیار کی۔ جس کی وجہ سے وہ اس مسئلہ میں صحیح رائے قائم نہ کرسکے۔ اصل قابلِ رجوع چیز تو کتاب وسنت ہے، جیسا کہ فرمان باری تعالیٰ ہے:\n﴿ فَإِن تَنَٰزَعۡتُمۡ فِي شَيۡءٍ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ ﴾ [النساء: ۵۹]\n’’اگر کسی مسئلہ میں تمہارا اختلاف ہو تو اسے اللہ اور رسول صلی اللہ علیہ وسلم کی طرف لوٹا دو۔‘‘","",{"k":"شرح السنۃ لللالکائي: 2/234 – 312۔ اس میں انہوں نے مذکورہ بالا علماء اور ان کے علاوہ دیگر علماء کے اقوال نقل کیے ہیں جن کی کل تعداد تقریباً ساڑھے پانچ سو ہے۔ سب کا یہی موقف تھا کہ قرآن کلام اللہ ہے اور غیر مخلوق ہے۔"}],[224,"سیدنا عمرو بن عوف رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے ایک خط میں لکھا: ’’جب تمہارا کسی معاملہ میں اختلاف ہوجائے گا تو اسے اللہ اور محمد صلی اللہ علیہ وسلم کی طرف لوٹایا جائے گا۔‘‘","",{"k":"جزء القراءۃ للبخاري، ص: 61۔ یہ جملہ اس میثاق مدینہ کا حصہ ہے جو مسلمانوں اور یہودیوں کے درمیان طے پایا تھا۔ میثاق مدینہ کی تفصیلات کےلیے ملاحظہ کیجیے: السیرۃ النبویۃ لابن إسحاق: 2/501 – 504۔ غریب الحدیث لأبي عبید القاسم بن سلام: 1/28"}],[225,"نبی کریم صلی اللہ علیہ وسلم کا فرمان گرامی ہے: ’’جس نے کوئی ایسا عمل کیا جس پر ہمارا حکم نہ تھا، تو وہ عمل مردود ہے۔‘‘\nہم تک یہ روایت علاء بن عبد الجبار از عبد اللہ بن جعفر مخزومی از سعد بن ابراہیم از قاسم از عائشہ رضی اللہ عنہا کی سند سے پہنچی ہے۔","",{"k":"صحیح مسلم: 3/1343 – 1344، رقم: 1718۔ امام بخاری نے صحیح بخاری میں اسے دو جگہ کتاب البیوع اور کتاب الاعتصام بالکتاب والسنۃ میں معلقاً بیان کیا ہے۔"}],[226,"عمر رضی اللہ عنہ نے حکم جاری فرمایا کہ لاعلمی پر مبنی کاموں کو سنت پر پرکھا جائے۔","",{"k":"سنن سعید بن منصور (1/355)۔ السنن الکبری للبیھقي (7/442)"}],[227,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’جو بندہ کلام اللہ کے بارے میں یہ نہیں جانتا کہ یہ غیر مخلوق ہے، اسے تعلیم دی جائے گی اور اس کی جہالت کو کتاب وسنت کے ذریعہ دور کیا جائے گا۔ پھر جو جاننے کے بعد بھی انکار کرے تو وہ معاند شمار ہوگا۔ فرمان باری تعالیٰ ہے:\n﴿ وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوۡمَۢا بَعۡدَ إِذۡ هَدَىٰهُمۡ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَۚ ﴾ [التوبۃ: ۱۱۵]\n’’اللہ ایسا نہیں ہے کہ کسی قوم کو ہدایت دینے کے بعد گمراہ کردے یہاں تک کہ اس کے سامنے وہ چیزیں واضح کردے جن سے وہ بچیں۔‘‘\nدوسری جگہ فرمایا:\n﴿ وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُ ٱلۡهُدَىٰ وَيَتَّبِعۡ غَيۡرَ سَبِيلِ ٱلۡمُؤۡمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصۡلِهِۦ جَهَنَّمَۖ وَسَآءَتۡ مَصِيرًا ﴾ [النساء: ۱۱۵]\n’’اور جو شخص اپنے سامنے ہدایت واضح ہونے کے بعد بھی رسول کی مخالفت کرے، اور مومنوں کے راستے کے سوا کسی اور راستے کی پیروی کرے، اس کو ہم اسی راہ کے حوالے کردیں گے جو اس نے خود اپنائی ہے، اور اسے دوزخ میں جھونکیں گے، اور وہ بہت برا ٹھکانا ہے۔‘‘"],[228,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’جہاں تک فریقین کا امام احمد کے مذہب کےلیے نصوص سے احتجاج کی بات ہے، جس کی طرف دونوں اپنا انتساب کرتے ہیں، تو ان میں سے اکثر روایات ثابت نہیں ہیں اور بعض اوقات فریقین امام احمد کے مذہب کی باریکی کو سمجھ نہیں پاتے۔"],[229,"بلکہ امام احمد اور دیگر اہل علم سے یہی موقف معروف ہے کہ کلام اللہ غیر مخلوق ہے۔ اللہ کے علاوہ سب کچھ مخلوق ہے۔ اہل علم نے گہری چیزوں کے بارے میں بحث مباحثہ اور ان کے درپے ہونے کو ناپسند کیا ہے۔وہ متکلمین سے دور رہتے ہیں اور گہری باتوں میں غور وخوض اور جھگڑے کو بھی ناپسند کرتے ہیں۔ صرف اس بات کو لیتے ہیں جس کا علم آچکا ہے اور رسول اللہ صلی اللہ علیہ وسلم اسے واضح کرچکے ہیں۔"],[230,"سیدنا عبد اللہ بن عمرو بن عاص رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کچھ لوگوں کو آپس میں بحث مباحثہ کرتے سنا تو فرمایا: ’’تم سے پہلے لوگ اسی وجہ سے ہلاک ہوئے تھے کہ کتاب اللہ کے ایک حصے کو دوسرے حصے سے ٹکراتے تھے۔ اللہ تعالیٰ نے جو کتاب نازل کی ہے، اس کا ایک حصہ دوسرے حصے کی تصدیق کرتا ہے۔ اس لیے ایک حصے کو دوسرے حصے سے نہ ٹکراؤ۔ جس چیز کا تمہیں علم ہے، وہ کہو اور جس کا علم نہ ہو، اسے اس کو جاننے والے کے سپرد کردو۔‘‘","",{"k":"مصنف عبد الرزاق (11/216 – 217)۔ مسند أحمد (2/185)"}],[231,"امام بخاری رحمہ اللہ فرماتے ہیں: ’’آدمی پر جب کوئی چیز مشتبہ ہوجائے تو اس کے لیے مناسب یہی ہے کہ اسے اس بات کو جاننے والے کے سپرد کردے جیسا کہ عبد اللہ بن عمرو رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جو تمہارے لیے مشکل ہوجائے، اسے اس کے عالم کے سپرد کردو۔‘‘ آدمی کو متشابہات میں دخل دینے کی بجائے واضح چیزوں کو اپنانا چاہیے۔‘‘"],[232,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اس آیت کی تلاوت فرمائی:\n﴿ هُوَ ٱلَّذِيٓ أَنزَلَ عَلَيۡكَ ٱلۡكِتَٰبَ مِنۡهُ ءَايَٰتٌ مُّحۡكَمَٰتٌ هُنَّ أُمُّ ٱلۡكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتٌۖ فَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِمۡ زَيۡغٌ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنۡهُ ٱبۡتِغَآءَ ٱلۡفِتۡنَةِ وَٱبۡتِغَآءَ تَأۡوِيلِهِۦۖ وَمَا يَعۡلَمُ تَأۡوِيلَهُۥٓ إِلَّا ٱللَّهُۗ وَٱلرَّٰسِخُونَ فِي ٱلۡعِلۡمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلٌّ مِّنۡ عِندِ رَبِّنَاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ ﴾ [آل عمران: ۷]\n’’وہی تو ہے جس نے آپ پر کتاب نازل کی۔ جس کی کچھ آیات تو محکم ہیں اور یہی (محکمات) کتاب کی اصل بنیاد ہیں اور دوسری متشابہات ہیں۔ اب جن لوگوں کے دل میں کجی ہے (پہلے ہی کسی غلط نظریہ پر یقین رکھتے ہیں) وہ فتنہ انگیزی کی خاطر متشابہات ہی کے پیچھے پڑے رہتے ہیں۔ اور انہیں اپنے حسب منشا معنی پہنانا چاہتے ہیں حالانکہ ان کا صحیح مفہوم اللہ کے سوا کوئی بھی نہیں جانتا۔ اور جو علم میں پختہ کار ہیں وہ کہتے ہیں کہ ہم ان (متشابہات) پر ایمان لاتے ہیں۔ ساری ہی آیات ہمارے پروردگار کی طرف سے ہیں۔ اور کسی چیز سے سبق تو صرف عقلمند لوگ ہی حاصل کرتے ہیں۔‘‘\nپھر آپ صلی اللہ علیہ وسلم نے فرمایا: جب تم ایسے لوگوں کو دیکھو جو متشابہات کے درپے ہوتے ہیں تو یہی لوگ ہیں جن کا ذکر اللہ تعالیٰ نے اس آیت میں کیا ہے۔ ان سے بچو۔‘‘","",{"k":"صحیح البخاري (4547)۔ صحیح مسلم (2665)"}],[233,"سیدنا عبد اللہ بن مسعود رضی اللہ عنہ فرماتے ہیں: جس کے پاس کسی چیز کا علم ہو، اسے اس کے بارے میں گفتگو کرنی چاہیے اور جس کے پاس علم نہ ہو، اسے ’’اللہ اعلم‘‘ کہنا چاہیے کیونکہ بندہ جس بات کو نہیں جانتا، اس کے بارے میں ’’اللہ اعلم‘‘ کہنا بھی علم کی دلیل ہے۔ کیونکہ اللہ عز وجل نے اپنے نبی صلی اللہ علیہ وسلم سے فرمایا:\n﴿ قُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍ وَمَآ أَنَا۠ مِنَ ٱلۡمُتَكَلِّفِينَ ﴾ [صٓ: ۸۶]\n’’ کہہ دیجیے: میں تم سے اس (تبلیغ) پر کوئی اجرت نہیں مانگتا اور نہ میں بناوٹ کرنے والوں سے ہوں۔‘‘"],[234,"محمد بن کثیر از سفیان از منصور اور اعمش از ابی الضُحی از مسروق کی سند سے مروی ہے، وہ کہتے ہیں کہ میں سیدنا عبد اللہ بن مسعود رضی اللہ عنہ کی خدمت میں حاضر ہوا۔ پھر انہوں نے ان کا درج بالا قول ذکر کیا۔","",{"k":"صحیح البخاري (4774)۔ صحیح مسلم (2798)"}],[235,"اس کے علاوہ آپ صلی اللہ علیہ وسلم کے اس فرمان سے بھی عبرت حاصل کرو: ’’اے اللہ! میری قوم کو بخش دے کیونکہ یہ لا علم ہیں۔‘‘","",{"k":"صحیح البخاري (3477)۔ صحیح مسلم (1792)"}],[236,"سیدنا ابو ثعلبہ رضی اللہ عنہ بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم دیکھو کہ بخیلی ہو رہی ہے، خواہش نفس کی پیروی کی جارہی ہے،دنیا کو ترجیح دی جارہی ہے اور ہر صاحب رائے اپنی رائے میں مگن ہے، تو اس وقت تم اپنی ذات کا دھیان کرنا اور عوام کو چھوڑ دینا۔‘‘","",{"k":"سنن أبي داود: 4/512، رقم: 4341۔ سنن الترمذي: 5/257، رقم: 3058۔ سنن ابن ماجہ: 2/1330، رقم: 4014۔ عتبہ بن ابی حکیم اور عمرو بن جاریہ لخمی کے مجہول الحال ہونے کی وجہ سے سند ضعیف ہے۔"}],[237,"فرمان الٰہی ہے:\n﴿ إِنَّا وَجَدۡنَٰهُ صَابِرًاۚ نِّعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٌ ﴾ [صٓ: ۴۴]\n’’حقیقت یہ ہے کہ ہم نے انہیں بڑا صبر کرنے والا پایا، وہ بہترین بندے تھے، واقعہ وہ اللہ سے خوب لَو لگائے ہوئے تھے۔‘‘\nدوسرے مقام پر فرمایا:\n﴿ أَلَمۡ تَرَ أَنَّهُمۡ فِي كُلِّ وَادٍ يَهِيمُونَ ﴾ [الشعراء: ۲۲۵]\n’’کیا تم دیکھتے نہیں کہ وہ (خیالوں کی) ہر وادی میں بھٹکتے پھرتے ہیں۔‘‘\nاور فرمایا:\n﴿ إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَواْ وَّٱلَّذِينَ هُم مُّحۡسِنُونَ ﴾ [النحل: ۱۲۸]\n’’بلاشبہ اللہ ان لوگوں کے ساتھ ہے جو اس سے ڈرتے ہیں اور جو اچھے کام کرتے ہیں۔‘‘"],[238,"امام بخاری رحمہ اللہ فرماتے ہیں کہ میں نے موسیٰ بن اسماعیل سے سنا، وہ کہہ رہے تھے کہ میں نے ابو عاصم ضحاک بن مخلد بن ضحاک نبیل (المتوفیٰ: 212ھ) کو کہتے ہوئے سنا: ’’جب سے مجھے معلوم ہوا کہ غیبت کرنے سے غیبت کرنے والے کو ہی نقصان ہوتا ہے، میں نے کبھی کسی کی غیبت نہیں کی۔‘‘","",{"k":"التاریخ الکبیر للبخاري: 4/336۔ یہ بات خود امام بخاری سے بھی منقول ہے۔ دیکھیے: طبقات الحنابلۃ لابن أبي یعلیٰ: 1/276 اور تاریخ بغداد للخطیب البغدادي: 2/63"}],[239,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’دو کلمات رحمن کو بہت محبوب ہیں جو زبان پر ادائیگی کے اعتبار سے بہت ہلکے ہیں لیکن ترازو میں بہت بھاری تُلیں گے، وہ کلمات یہ ہیں: «سبحان اللہ وبحمدہ، سبحان اللہ العظیم» ’’اللہ تعالیٰ اپنی تعریف کے ساتھ پاک ہے، اللہ تعالیٰ جو بہت عظمتوں والا ہے، پاک ہے۔‘‘","",{"k":"صحیح البخاري (7563)۔ صحیح مسلم (2694)"}],[240,"سیدنا عبداللہ بن مسعود رضی اللہ عنہ نے بیان کیاکہ خانہ کعبہ کے پاس دو قریشی اور ایک ثقفی یا ایک قریشی اور دو ثقفی مرد بیٹھے ہوئے تھے۔ ان کے پیٹ بہت موٹے تھے لیکن عقل سے کورے تھے۔ ان میں سے ایک نے کہا: ’’تمہارا کیا خیال ہے، کیا اللہ ہماری باتوں کو سن رہا ہے؟‘‘ دوسرے نے کہا: ’’اگر ہم زور سے بولیں تو سنتا ہے لیکن آہستہ بولیں تو نہیں سنتا۔‘‘ تیسرے نے کہا: ’’اگر اللہ زور سے بولنے پر سن سکتا ہے تو آہستہ بولنے پہ بھی ضرور سنتا ہو گا۔‘‘اس پر یہ آیت نازل ہوئی: ﴿ وَمَا كُنتُمۡ تَسۡتَتِرُونَ أَن يَشۡهَدَ عَلَيۡكُمۡ سَمۡعُكُمۡ وَلَآ أَبۡصَٰرُكُمۡ وَلَا جُلُودُكُمۡ ﴾ الآیۃ [فصلت: ۲۲] ”اور تم اس بات سے اپنے کو چھپا ہی نہیں سکتے کہ تمہارے کان اور تمہاری آنکھیں اور تمہارے چمڑے گواہی دیں گے۔“ آخر آیت تک۔","",{"k":"صحیح البخاري (4817، 7521)۔ صحیح مسلم (2775)"}],[241,"اسحاق بن منصور از عبد الرحمن بن مہدی از حماد بن زید از یحییٰ بن عتیق کی سند سے مروی ہے کہ محمد بن سیرین انصاری (المتوفیٰ: 110ھ) نے فرمایا: ’’کہا جاتا تھا کہ تاجر پر تعجب ہے کہ کیسے تجارت کرلیتا ہے؟‘‘ یحییٰ نے کہا: ’’وہ سچ بولتا ہے اور ایسے ایسے کرتا ہے۔‘‘ محمد کہتے ہیں: ’’پھر یحییٰ نے تجارت میں میرے ساتھ شراکت داری کی تو مجھے کہا: ’’پیارے بھائی! مجھے تو ہر چیز شک میں ڈال رہی ہے۔‘‘ محمد کہتے ہیں: میں نے اس بات کا تذکرہ حُمَید بن عبد الرحمن (المتوفیٰ: 105ھ)سے کیا تو انہوں نے فرمایا: ’’اب (ان کی سمجھ میں آیا ہے) جب انہوں نے سب کچھ دیکھ لیا ہے۔‘‘"],[242,"سیدنا حذیفہ رضی اللہ عنہ فرماتے ہیں: ’’لوگوں پر ایسا زمانہ بھی آئے گا جب ان کےلیے وہی درست ہوگا جس سے انہیں منع کیا گیا ہے یعنی ہجرت کے بعد بادیہ نشینی اختیار کرنا۔‘‘","",{"k":"الزھد لھناد: 2/586، رقم: 1244۔ سند منقطع ہے کیونکہ ابو حَصِیْن نے ابو حذیفہ کو نہیں پایا۔"}],[243,"بسم اللہ الرحمن الرحیم\nامام بخاری رحمہ اللہ فرماتے ہیں: ’’اہل علم سےاسی عقیدہ پر ملو اور جاہلوں سے اعراض کرلو، یوں وہ اہل بدعت کی طرح بکھر جائیں گے۔ فرمان الٰہی ہے:\n﴿ إِنَّ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعًا لَّسۡتَ مِنۡهُمۡ فِي شَيۡءٍۚ ﴾ [الأنعام: ۱۵۹]\n’’(اے پیغمبر) یقین جانو کہ جن لوگوں نے اپنے دین میں تفرقہ پیدا کیا ہے، اور گروہوں میں بٹ گئے ہیں، ان سے تمہارا کوئی تعلق نہیں ہے۔‘‘","",{"k":"یہ حمزہ اور کسائی کی قراءت کے مطابق ہے۔دیگر قراء کرام نے ’’فَرَّقُوْا‘‘ پڑھا ہے۔"}],[244,"طاؤس سے مروی ہے، وہ ابو ہریرہ رضی اللہ عنہ سے بیان کرتے ہیں کہ انہوں نے فرمایا: ’’یہ(فرقہ بندی) اس امت میں موجود ہے۔‘‘","",{"k":"تفسیر ابن جریر: 8/105۔ اس کی سند میں لیث بن ابی سلیم ہے۔ یہ مرفوعاً بھی مروی ہے، لیکن مرفوعاً درست نہیں۔"}],[245,"شعبی سے مصحف کی خرید وفروخت کے بارے میں پوچھا گیا تو انہوں نے فرمایا: ’’دکاندار کتاب اللہ نہیں بیچتا، وہ تو اپنے ہاتھوں کی کاریگری کو بیچتا ہے۔‘‘","",{"k":"مصنف عبد الرزاق: 8/113، مصنف ابن أبي شیبۃ: 6/64۔ سنن سعید بن منصور: 2/377۔ اس کی سند شعبی تک صحیح ثابت ہے۔"}],[246,"ابن عباس رضی اللہ عنہ فرماتے ہیں: ’’مصحف خرید لو، لیکن فروخت نہ کرو۔‘‘","",{"k":"مصنف عبد الرزاق: 8/112، سنن سعید بن منصور: 2/379، فضائل القرآن لأبي عبید: 2/226، رقم: 881۔ یہ اور اسناد سے بھی مروی ہے، اس لیے مجموعی طور پر یہ ابن عباس سے ثابت ہے۔"}],[247,"زیاد مولیٰ سعد کہتے ہیں کہ میں نے ابن عباس رضی اللہ عنہ سے پوچھا تو انہوں نے فرمایا: ’’ہماری رائے میں تمہارا اس کام کو تجارت بنانادرست نہیں۔ لیکن جو تمہارے ہاتھوں کی کمائی ہے، اس میں کوئی حرج نہیں۔‘‘","",{"k":"المدونۃ الکبری: 4/418۔ السنن الکبری للبیھقي: 6/16۔ زیاد مولیٰ سعد کی وجہ سے یہ سند ضعیف ہے۔ لیکن چونکہ سائل بھی یہی ہے، اس لیے صحت کے قریب تر بات یہی ہے کہ اس نے یہ بات یاد رکھی ہوگی۔ واللہ اعلم"}],[248,"سیدنا ابن عباس رضی اللہ عنہ کے بارے میں منقول ہے کہ وہ مصحف کو فروخت کرنے اور اس کی قیمت سے اس سے بہتر مصحف خریدنے میں کوئی حرج نہیں سمجھتے تھے۔ ان کے نزدیک مصحف کا مصحف سے تبادلہ کرنے میں کوئی حرج نہیں۔ اس لیے انہوں نے مصحف کو خریدنے کی اجازت دی ہے۔","",{"k":"یہ اثر پہلے بھی آچکا ہے، لیکن اس کے مصدر کا علم نہیں ہوسکا۔"}],[249,"عبید اللہ بن سلیمان کہتے ہیں کہ میں نے سعید بن مسیب سے مصحف کی کتابت کے بارے میں دریافت کیا تو انہوں نے فرمایا: ’’اس میں کوئی حرج نہیں۔ ابن عباس رضی اللہ عنہ کا ایک نوکر سو (درہم یا دینار) کے عوض مصحف لکھا کرتا تھا۔‘‘","",{"k":"سند صحیح ہے۔"}],[250,"جابر بن عبد اللہ رضی اللہ عنہ فرماتے ہیں: ’’مصحف کو خریدنا مجھے اس کو فروخت کرنے سے زیادہ محبوب ہے۔‘‘","",{"k":"فضائل القرآن لأبي عبید (882)۔ مصنف ابن أبي شیبۃ (6/63)"}],[251,"ابن عباس رضی اللہ عنہ مصاحف کا کاروبار کرنے کے بارے میں فرماتے ہیں: ’’یہ لوگ مصور ہیں جو اپنے ہاتھ کی کاریگری کو فروخت کرتے ہیں۔‘‘","",{"k":"المصاحف لابن أبي داود (ص 147)"}],[252,"علی رضی اللہ عنہ سے منقول ہے کہ انہوں نے فرمایا: ’’لوگوں پر ایک وقت ایسا آئے گا کہ اسلام کا صرف نام اور قرآن کے صرف حروف رہ جائیں گے۔‘‘","",{"k":"الکامل في الضعفاء لابن عدي: 4/227۔ یہ عبد اللہ بن دکین کی منکر روایات میں سے ہے۔ السنن الواردۃ في الفتن لأبي عمرو الداني: 3/545۔ شعب الإیمان للبیھقي: 2/211 – 212 میں مرفوعاً مروی ہے لیکن سنداً صحیح نہیں ہے۔"}],[253,"نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’قرآن کو اپنی آوازوں سے مزین کرو۔‘‘","",{"k":"اس کی تخریج 263 تا 271 میں آرہی ہے۔"}],[254,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی کریم صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ’’اللہ تعالیٰ نے کسی چیز کے لیے اس قدر کان نہیں لگائے جس قدر اس نبی کی آواز سننے کےلیے کان لگائے جو اونچی آواز سے قرآن پڑھتا ہے۔‘‘","",{"k":"صحیح البخاري (7544)۔ صحیح مسلم (792)"}],[255,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ نے کسی چیز کےلیے اس قدر کان نہیں لگائے جس قدر اس نبی کےلیے جو خوبصورت آواز کے ساتھ قرآن پڑھتا ہے۔‘‘","",{"k":"صحیح البخاري (5023، 7482)۔ صحیح مسلم (792)"}],[256,"امام بخاری رحمہ اللہ فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے ابو موسیٰ رضی اللہ عنہ کی قراءت سنی تو فرمایا: ’’ابو موسیٰ کو آل داؤد کے مزامیر (یعنی خوبصورت آواز)دیے گئے ہیں۔‘‘"]])